package com.mixologybeltrunner;

public enum BeltColour
{
	NONE,
	GREEN
}

package com.mixologybeltrunner;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

/**
 * Decides whether clicking the conveyor belt is worth it for the current orders. Any click
 * that fills one order brings a whole new set, so the belt is worth clicking whenever
 * something fills and no unfilled order is worth making first (see {@link Mode#worthMaking}).
 */
public final class BeltRules
{
	private static final int ORDER_COUNT = 3;
	private static final Comparator<Order> BEST_FIRST = Comparator.comparingInt((Order o) -> o.type().xp()).reversed();

	private BeltRules()
	{
	}

	/**
	 * Returns null unless all three orders are known.
	 */
	public static BeltVerdict evaluate(List<Order> orders, SlotMap map, Mode mode)
	{
		if (orders == null || orders.size() != ORDER_COUNT)
		{
			return null;
		}

		boolean[] claimed = new boolean[SlotMap.SIZE];
		List<Order> unfilled = new ArrayList<>();
		List<Order> worthMaking = new ArrayList<>();
		int fills = 0;
		for (Order o : orders)
		{
			if (claim(o, map, claimed))
			{
				fills++;
			}
			else
			{
				unfilled.add(o);
				if (mode.worthMaking(o.type()))
				{
					worthMaking.add(o);
				}
			}
		}
		if (unfilled.isEmpty())
		{
			return new BeltVerdict(BeltState.ALL_FILLABLE, null, Collections.emptyList(), unfilled, fills);
		}
		if (worthMaking.isEmpty() && fills >= 1)
		{
			return new BeltVerdict(BeltState.SKIPPING, null, unfilled, unfilled, fills);
		}
		if (!worthMaking.isEmpty())
		{
			return new BeltVerdict(BeltState.NEED_ORDER, best(worthMaking), Collections.emptyList(), unfilled, fills);
		}
		return new BeltVerdict(BeltState.NOTHING_FILLABLE, best(unfilled), Collections.emptyList(), unfilled, fills);
	}

	/**
	 * The cells a closed belt needs made, in board order: every unfilled order worth making,
	 * or the best unfilled order when nothing can be filled. Empty for an open belt or
	 * unknown orders. Two orders for the same cell give one entry; the guide counts the
	 * demand itself.
	 */
	public static Set<Cell> neededCells(BeltVerdict v, Mode mode)
	{
		Set<Cell> out = new LinkedHashSet<>();
		if (v == null)
		{
			return out;
		}
		switch (v.state())
		{
			case NEED_ORDER:
				for (Order o : v.unfilled())
				{
					if (mode.worthMaking(o.type()))
					{
						out.add(new Cell(o.type(), o.station()));
					}
				}
				break;
			case NOTHING_FILLABLE:
				out.add(new Cell(v.toMake().type(), v.toMake().station()));
				break;
			default:
				break;
		}
		return out;
	}

	private static Order best(List<Order> orders)
	{
		List<Order> sorted = new ArrayList<>(orders);
		sorted.sort(BEST_FIRST);
		return sorted.get(0);
	}

	private static boolean claim(Order o, SlotMap map, boolean[] claimed)
	{
		for (int i = 0; i < SlotMap.SIZE; i++)
		{
			PotionSlot p = map.get(i);
			if (!claimed[i] && p != null && p.processed() && p.type() == o.type() && p.station() == o.station())
			{
				claimed[i] = true;
				return true;
			}
		}
		return false;
	}
}

package com.mixologybeltrunner;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(BeltRunnerConfig.GROUP)
public interface BeltRunnerConfig extends Config
{
	String GROUP = "mixologybeltrunner";

	@ConfigSection(
		name = "Colours",
		description = "Highlight colours in the lab",
		position = 10
	)
	String coloursSection = "colours";

	@ConfigItem(
		keyName = "mode",
		name = "Mode",
		description = "Focus XP: stock the five best potions and click the belt whenever anything fills. Balanced: stock all seven, make unfilled Anti-leech lotion and Mixalot orders first, for more resin, split evenly, at a few percent less XP.",
		position = -1
	)
	default Mode mode()
	{
		return Mode.FOCUS_XP;
	}

	@ConfigItem(
		keyName = "windowStyle",
		name = "Window style",
		description = "How much the guide window shows: the next step, a to-do list, or every potion and station",
		position = 0
	)
	default WindowStyle windowStyle()
	{
		return WindowStyle.NEXT_STEP;
	}

	@ConfigItem(
		keyName = "restockThreshold",
		name = "Restock at",
		description = "When the belt locks, restock everything once this much of the stock is missing. Below it, only the potion for the current order is made. Early restocks are faster: each trip to make potions costs the same walk however many you make.",
		position = 1
	)
	@Range(min = 1, max = 100)
	@Units(Units.PERCENT)
	default int restockThreshold()
	{
		return 10;
	}

	@ConfigItem(
		keyName = "holdDigweed",
		name = "Hold digweed",
		description = "Save digweed for an ordered Mixalot. When off, it goes on any Mixalot you hold, or else the best ordered potion.",
		position = 2
	)
	default boolean holdDigweed()
	{
		return false;
	}

	@ConfigItem(
		keyName = "stationGuard",
		name = "Station guard",
		description = "Ignore clicks on an empty station when the next potion is meant for a different one",
		position = 3
	)
	default boolean stationGuard()
	{
		return true;
	}

	@ConfigItem(
		keyName = "leverGuard",
		name = "Lever guard",
		description = "Ignore pulls on a lever that is not the next one the potion needs",
		position = 4
	)
	default boolean leverGuard()
	{
		return true;
	}

	@ConfigItem(
		keyName = "pathDisplay",
		name = "Path",
		description = "Where to draw the walking path to the next thing to click",
		position = 6
	)
	default PathDisplay pathDisplay()
	{
		return PathDisplay.FLOOR_AND_MINIMAP;
	}

	@ConfigItem(
		keyName = "beltLock",
		name = "Belt lock",
		description = "Ignore clicks on the conveyor belt while a deposit is not worth making",
		position = 5
	)
	default boolean beltLock()
	{
		return true;
	}

	@ConfigItem(
		keyName = "highlightColour",
		name = "Highlight",
		description = "Station and vessel highlight",
		section = coloursSection,
		position = 0
	)
	default Color highlightColour()
	{
		return new Color(0xff981f);
	}

	@ConfigItem(
		keyName = "quickActionColour",
		name = "Bonus click colour",
		description = "Station while a bonus click is available",
		section = coloursSection,
		position = 1
	)
	default Color quickActionColour()
	{
		return Color.GREEN;
	}

	@ConfigItem(
		keyName = "beltOpenColour",
		name = "Belt open",
		description = "Conveyor belt when a deposit is worth making",
		section = coloursSection,
		position = 2
	)
	default Color beltOpenColour()
	{
		return new Color(0x00e676);
	}

	@ConfigItem(
		keyName = "digweedColour",
		name = "Digweed",
		description = "Digweed spot and the potion to use it on",
		section = coloursSection,
		position = 3
	)
	default Color digweedColour()
	{
		return new Color(0x39ff14);
	}
}

package com.mixologybeltrunner;

import com.google.gson.Gson;
import com.google.inject.Provides;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.MenuAction;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.GraphicsObjectCreated;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.MenuOptionClicked;
