	MISSING
}

package com.mixologybeltrunner;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Reads the lab's game messages.
 */
public final class ChatParse
{
	private static final Pattern TAGS = Pattern.compile("<[^>]*>|@[^@\\s]*@");
	private static final Pattern FAILED_DEPOSIT = Pattern.compile("^You deposit some (.+), but fail to fulfil an order\\.$");

	private ChatParse()
	{
	}

	/**
	 * The potion named in "You deposit some X, but fail to fulfil an order.", or null for
	 * any other message. Colour tags and the game's {@code @mes_hl_pur@} style markers are
	 * stripped first.
	 */
	public static PotionType failedDeposit(String message)
	{
		if (message == null)
		{
			return null;
		}
		Matcher m = FAILED_DEPOSIT.matcher(TAGS.matcher(message).replaceAll("").trim());
		return m.matches() ? PotionType.fromItemName(m.group(1).trim()) : null;
	}
}

package com.mixologybeltrunner;

/**
 * Decides which clicks to swallow before they reach the game.
 */
public final class ClickGuard
{
	private ClickGuard()
	{
	}

	/**
	 * True for a click on an idle station when the next potion is planned for another one.
	 * A station that already holds a potion is never blocked: its clicks drive the process.
	 */
	public static boolean blockStation(Station clicked, boolean clickedOccupied, Station plannedForFirstUnprocessed)
	{
		return plannedForFirstUnprocessed != null && !clickedOccupied && clicked != plannedForFirstUnprocessed;
	}

	/**
	 * True for a lever pull that is not the next one the potion needs, and for any pull while
	 * the finished potion waits in the vessel. No numbers and nothing waiting never blocks.
	 */
	public static boolean blockLever(java.util.Map<PotionComponent, java.util.List<Integer>> numbers,
		boolean potionWaiting, PotionComponent clicked)
	{
		if (potionWaiting)
		{
			return true;
		}
		PotionComponent next = null;
		int lowest = Integer.MAX_VALUE;
		for (java.util.Map.Entry<PotionComponent, java.util.List<Integer>> e : numbers.entrySet())
		{
			for (int n : e.getValue())
			{
				if (n < lowest)
				{
					lowest = n;
					next = e.getKey();
				}
			}
		}
		return next != null && clicked != next;
	}

	/**
	 * True when the belt is locked. No verdict (orders unknown) never blocks.
	 */
	public static boolean blockBelt(BeltVerdict verdict)
	{
		return verdict != null && !verdict.state().open();
	}

	/**
	 * Also blocks a second belt click in the same tick. A tick hands in once, and a click
	 * that reaches the server late lands after that hand-in has brought new orders, where
	 * it can fail to fulfil and lose a potion.
	 */
	public static boolean blockBelt(BeltVerdict verdict, boolean clickedThisTick)
	{
		return clickedThisTick || blockBelt(verdict);
	}
}

package com.mixologybeltrunner;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Supplier;

/**
 * Turns the tracked state into one instruction per tick: restock, process, then
 * work the belt until it locks, then top up or restock.
 */
public final class Guide
{
	private static final String SEPARATOR = " · ";

	private Phase phase;
	/**
	 * The cells the current make batch should cover.
	 */
	private final Set<Cell> targets = new LinkedHashSet<>();
	/**
	 * The order cells the batch makes potions for; empty when none.
	 */
	private final Set<Cell> orderCells = new LinkedHashSet<>();
	/**
	 * True once the batch knows which orders it makes potions for.
	 */
	private boolean orderCellsDecided;
	/**
	 * True when the batch refills the plan, false for a top up of the orders alone.
	 */
	private boolean restocking;

	public Step next(GuideInput in)
	{
		if (in.rival != null)
		{
			reset();
			return Step.builder(Phase.DORMANT, "Belt Runner is paused")
				.status("Turn off " + in.rival + " to use it")
				.warning(warning(in))
				.build();
		}
		if (in.trackerState != TrackerState.TRACKING)
		{
			reset();
			return Step.builder(Phase.NEEDS_CLEAR, "Deposit or destroy your potions to start")
				.status(in.pauseReason != null ? in.pauseReason : "Tracking starts from an inventory with no potions")
				.warning(warning(in))
				.build();
		}

		if (phase == null)
		{
			startBatch(in.plan.missing(in.map, in.inStations), true, Collections.emptySet());
			phase = Phase.MAKE;
		}

		Step.Builder b = advance(in);
		phase = b.phase();
		headline(b, in);
		return b.rows(StockSummary.rows(in.plan, in.map, in.inStations))
			.stock(stockHave(in), in.plan.size())
			.warning(warning(in))
			.build();
	}

	private static final String LOW_LEVEL_WARNING = "Not tested below Herblore 81. The XP rate assumes every potion is unlocked.";

	private static String warning(GuideInput in)
	{
		return in.lowLevelWarning ? LOW_LEVEL_WARNING : "";
	}

	/**
	 * Picks the station for a potion that has just come out of the vessel: the one the
	 * current step asked for when the potion is the type it asked for, otherwise the
	 * plan's best guess.
	 */
	static InventoryTracker.StationAssigner assigner(Supplier<Step> step, Supplier<StockPlan> plan, Supplier<List<Order>> orders)
	{
		return (map, inStations, type) -> stationFor(step.get(), plan.get(), orders.get(), map, inStations, type);
	}

	static Station stationFor(Step step, StockPlan plan, List<Order> orders, SlotMap map,
		Map<Station, PotionSlot> inStations, PotionType type)
	{
		if (step != null && step.make() == type && step.station() != null)
		{
			return step.station();
		}
		return plan.assignStation(map, inStations, type, orders);
	}

	public void reset()
	{
		phase = null;
		targets.clear();
		orderCells.clear();
		orderCellsDecided = false;
		restocking = false;
	}

	private Step.Builder advance(GuideInput in)
	{
		if (phase == Phase.MAKE)
		{
			Step.Builder b = make(in);
			if (b != null)
			{
				return b;
			}
			phase = Phase.PROCESS;
		}
		if (phase == Phase.PROCESS)
		{
			Step.Builder b = process(in);
			if (b != null)
			{
				return b;
			}
			phase = Phase.BELT;
		}
		return belt(in);
	}

	/**
	 * The next make step, or null when the batch is done.
	 */
	private Step.Builder make(GuideInput in)
	{
		decideOrderCells(in);
		Cell next = nextCell(in, null);
		if (in.vesselReady != null)
		{
			Cell taken = next != null && next.type() == in.vesselReady ? next : nextCell(in, in.vesselReady);
			if (taken != null || next == null)
			{
				return Step.builder(Phase.MAKE, "Take the potion")
					.make(in.vesselReady)
					.station(taken == null ? null : taken.station())
					.highlightVessel(true);
			}
			// The vessel made a potion nobody wants: keep pulling for the next one instead.
		}
		if (next == null)
		{
			return null;
		}

		PotionType type = next.type();
		boolean planGap = restocking && in.plan.contains(type) && StockPlan.covered(in.map, in.inStations, next) == 0;
		Step.Builder b;
		if (orderCells.contains(next) && !planGap)
		{
			b = Step.builder(Phase.MAKE, makeOrderHeadline(next))
				.status(in.plan.contains(type) ? "Top up" + SEPARATOR + "for the current order"
					: "Not stocked" + SEPARATOR + "just for this order");
		}
		else
		{
			b = Step.builder(Phase.MAKE, "Make " + type.code())
				.status(join("Restocking", "round " + in.plan.round(in.map, in.inStations) + " of 3", stockPart(in)));
		}
		b.make(type).station(next.station());
		if (Vessel.wrongPull(type, in.vesselSlots))
		{
			b.status(join(b.status(), "wrong lever, start again"));
		}
		return b.leverNumbers(Vessel.pullNumbers(type, in.vesselSlots));
	}

	/**
	 * The next batch cell to make, or null when every one has its potions; only cells of
	 * {@code type} when it is not null. A new potion lands in the lowest empty slot, so the
	 * pick is the first cell, in make order, whose station fits between the unprocessed
	 * potions below and above that slot. When none fits, or the inventory is full, it is
	 * simply the first cell in make order.
	 */
	private Cell nextCell(GuideInput in, PotionType type)
	{
		List<Cell> candidates = new ArrayList<>();
		for (Cell cell : in.plan.makeOrder(targets))
		{
			if ((type == null || cell.type() == type) && StockPlan.covered(in.map, in.inStations, cell) < need(in, cell))
			{
				candidates.add(cell);
			}
		}
		if (candidates.isEmpty())
		{
			return null;
		}
		if (in.landingSlot >= 0)
		{
			int lo = 0;
			int hi = Station.PROCESS_ORDER.size() - 1;
			for (int slot : in.map.occupiedSlots())
			{
				PotionSlot p = in.map.get(slot);
				if (p.processed())
				{
					continue;
				}
				int rank = rank(p.station());
				if (slot < in.landingSlot)
				{
					lo = Math.max(lo, rank);
				}
				else if (slot > in.landingSlot)
				{
					hi = Math.min(hi, rank);
				}
			}
			for (Cell cell : candidates)
			{
				int rank = rank(cell.station());
				if (lo <= rank && rank <= hi)
				{
					return cell;
				}
			}
		}
		return candidates.get(0);
	}

	private static int rank(Station station)
	{
		return Station.PROCESS_ORDER.indexOf(station);
	}

	/**
	 * Potions the batch wants for a cell: one, or as many as the orders ask for an order cell.
	 */
	private int need(GuideInput in, Cell cell)
	{
		return orderCells.contains(cell) ? Math.max(1, StockPlan.demand(in.orders, cell)) : 1;
	}

	/**
	 * A restock started without a locked belt works out whether the belt will lock once the
	 * batch is made. If so, the potions those orders need join the batch now, so each is
	 * made inside its station's block instead of after the last one.
	 */
	private void decideOrderCells(GuideInput in)
	{
		if (orderCellsDecided)
		{
			return;
		}
		BeltVerdict verdict = BeltRules.evaluate(in.orders, afterBatch(in), in.mode);
		if (verdict == null)
		{
			// Orders unknown: ask again next time.
			return;
		}
		orderCellsDecided = true;
		Set<Cell> needed = BeltRules.neededCells(verdict, in.mode);
		orderCells.addAll(needed);
		targets.addAll(needed);
	}

	/**
	 * The stock as it will be once every potion is processed and the batch's missing cells
	 * are made, as far as the inventory has room.
	 */
	private SlotMap afterBatch(GuideInput in)
	{
		SlotMap out = in.map.assumingProcessed();
		List<Cell> toAdd = new ArrayList<>();
		for (Station station : Station.PROCESS_ORDER)
		{
			PotionSlot loaded = in.inStations.get(station);
			if (loaded != null)
			{
				toAdd.add(new Cell(loaded.type(), station));
			}
		}
		for (Cell cell : targets)
		{
			if (StockPlan.covered(in.map, in.inStations, cell) == 0)
			{
				toAdd.add(cell);
			}
		}
		int slot = 0;
		for (Cell cell : toAdd)
		{
			while (slot < SlotMap.SIZE && out.get(slot) != null)
			{
				slot++;
			}
			if (slot == SlotMap.SIZE)
			{
				break;
			}
			out.put(slot, new PotionSlot(cell.type(), true, cell.station(), false));
		}
		return out;
	}

	/**
	 * The next station step, or null when nothing is left to process. The headline counts
	 * the run of potions the station takes before the next one is needed.
	 */
	private Step.Builder process(GuideInput in)
	{
		int first = in.map.firstUnprocessed();
		if (first >= 0)
		{
			List<String> runs = runs(in.map);
			return Step.builder(Phase.PROCESS, runs.get(0))
				.status(then(runs.subList(1, runs.size())))
				.station(in.map.get(first).station())
				.next(nextAfter(in.map, in.map.get(first).station()))
				.stationCount(firstRun(in.map))
				.nextPotionSlot(first);
		}
		Station busy = busyStation(in);
		return busy == null ? null : Step.builder(Phase.PROCESS, "Finish at " + busy.displayName()).station(busy).stationCount(0)
			.next(LabObject.CONVEYOR_BELT);
	}

	/**
	 * Where to go once the current station's run is done: the next station with unprocessed
	 * potions, in slot order, or the belt when there is none.
	 */
	static LabObject nextAfter(SlotMap map, Station current)
	{
		for (int slot : map.occupiedSlots())
		{
			PotionSlot p = map.get(slot);
			if (!p.processed() && p.station() != current)
			{
				return p.station().object();
			}
		}
		return LabObject.CONVEYOR_BELT;
	}

	/**
	 * How many unprocessed potions in a row, from the first one, share its station.
	 */
	static int firstRun(SlotMap map)
	{
		int first = map.firstUnprocessed();
		if (first < 0)
		{
			return 0;
		}
		Station station = map.get(first).station();
		int count = 0;
		for (int slot : map.occupiedSlots())
		{
			PotionSlot p = map.get(slot);
			if (p.processed())
			{
				continue;
			}
			if (p.station() != station)
			{
				break;
			}
			count++;
		}
		return count;
	}

	/**
	 * Potions still to load into a busy station: the run that follows, if it is the same station.
	 */
	private static int stillToLoad(SlotMap map, Station busy)
	{
		int first = map.firstUnprocessed();
		return first >= 0 && map.get(first).station() == busy ? firstRun(map) : 0;
	}

	/**
	 * The unprocessed potions as runs in slot order, each "Station ×count".
	 */
	private static List<String> runs(SlotMap map)
	{
		List<Station> stations = new ArrayList<>();
		List<Integer> counts = new ArrayList<>();
		for (int slot : map.occupiedSlots())
		{
			PotionSlot p = map.get(slot);
			if (p.processed())
			{
				continue;
			}
			int last = stations.size() - 1;
			if (last >= 0 && stations.get(last) == p.station())
			{
				counts.set(last, counts.get(last) + 1);
			}
			else
			{
				stations.add(p.station());
				counts.add(1);
			}
		}
		List<String> out = new ArrayList<>();
		for (int i = 0; i < stations.size(); i++)
		{
			out.add(stations.get(i).displayName() + " ×" + counts.get(i));
		}
		return out;
	}

	private static String then(List<String> runs)
	{
		return runs.isEmpty() ? "" : "then " + String.join(", ", runs);
	}

	/**
	 * The first station, in process order, holding a potion; null when all are free.
	 */
	private static Station busyStation(GuideInput in)
	{
		for (Station station : Station.PROCESS_ORDER)
		{
			if (in.inStations.get(station) != null)
			{
				return station;
			}
		}
		return null;
	}

	private Step.Builder belt(GuideInput in)
	{
		BeltVerdict verdict = BeltRules.evaluate(in.orders, in.map, in.mode);
		if (verdict == null)
		{
			return Step.builder(Phase.BELT, "Waiting for orders").status(stockPart(in));
		}
		if (verdict.state().open())
		{
			String headline = "Click the belt";
			if (verdict.state() == BeltState.SKIPPING)
			{
				List<String> codes = new ArrayList<>();
				for (Order o : verdict.skipped())
				{
					codes.add(o.type().code());
				}
				headline += " (skipping " + String.join(", ", codes) + ")";
			}
			return Step.builder(Phase.BELT, headline)
				.status(join("fills " + verdict.fills() + " of 3", stockPart(in)))
				.belt(BeltColour.GREEN)
				.verdict(verdict);
		}

		Cell toMake = cell(verdict.toMake());
		boolean restock = in.plan.needsRestock(in.map, in.inStations, in.restockThreshold);
		startBatch(restock ? in.plan.missing(in.map, in.inStations) : new LinkedHashSet<>(), restock,
			BeltRules.neededCells(verdict, in.mode));
		phase = Phase.MAKE;
		Step.Builder b = make(in);
		if (b == null)
		{
			// Unprocessed potions made off-script may already cover the orders.
			b = process(in);
		}
		if (b == null)
		{
			// Nothing to make or process: stay on the belt rather than loop back to it.
			phase = Phase.BELT;
			b = Step.builder(Phase.BELT, makeOrderHeadline(toMake))
				.status("Top up" + SEPARATOR + "for the current order")
				.make(toMake.type())
				.station(toMake.station());
		}
		return b.verdict(verdict);
	}

	/**
	 * @param orders the order cells a locked belt needs; empty when the batch works them
	 *               out itself once the orders are known
	 */
	private void startBatch(Set<Cell> cells, boolean restock, Set<Cell> orders)
	{
		targets.clear();
		targets.addAll(cells);
		targets.addAll(orders);
		orderCells.clear();
		orderCells.addAll(orders);
		orderCellsDecided = !orders.isEmpty();
		restocking = restock;
	}

	/**
	 * Lets the steps that outrank the phase step take the headline: a busy station, a
	 * ready vessel, digweed to use (only once the batch has nothing left to make), then
	 * digweed to pick up (only with a free slot to take it). The phase step underneath has
	 * already moved the guide's phase on.
	 */
	private void headline(Step.Builder b, GuideInput in)
	{
		LabObject spawn = in.digweedHeld ? null : in.digweedSpawn;
		String direction = spawn == null ? null : digweedDirection(spawn);
		b.digweedSpot(spawn);

		Station busy = busyStation(in);
		if (busy != null)
		{
			takeOver(b.phase(Phase.PROCESS), "Finish at " + busy.displayName())
				.status(join(then(runs(in.map)), direction == null ? "" : "digweed ready " + direction))
				.station(busy)
				.stationCount(stillToLoad(in.map, busy))
				.next(nextAfter(in.map, busy));
			return;
		}
		if (in.vesselReady != null && (b.phase() != Phase.MAKE || nextCell(in, in.vesselReady) != null))
		{
			if (b.phase() != Phase.MAKE)
			{
				takeOver(b, "Take the potion")
					.make(in.vesselReady)
					.highlightVessel(true)
					.next(null);
			}
			return;
		}
		if (in.digweedHeld)
		{
			int slot = digweedTarget(in);
			if (slot >= 0 && b.phase() == Phase.MAKE)
			{
				// A make step means potions are still to come. Using the digweed would free
				// its slot and land one of them out of station order; holding it costs nothing,
				// since the spawn count only moves on deliveries.
				b.status(join(b.status(), "use digweed after making"));
			}
			else if (slot >= 0)
			{
				b.headline("Use digweed on " + in.map.get(slot).type().code())
					.digweedSlot(slot)
					.digweedTarget(in.map.get(slot).type())
					.station(null)
					.nextPotionSlot(-1)
					.leverNumbers(Collections.emptyMap())
					.highlightVessel(false)
					.next(null)
					.belt(BeltColour.NONE);
			}
			else if (in.holdDigweed)
			{
				b.status(join(b.status(), "holding digweed for a Mixalot"));
			}
			return;
		}
		if (spawn != null && (in.landingSlot < 0 || mixing(in)))
		{
			// A full inventory has no room for it, and a potion half made in the vessel is
			// finished first; the spot stays marked.
			b.status(join(b.status(), "digweed ready " + direction));
		}
		else if (spawn != null)
		{
			b.headline("Pick up the digweed (" + direction + ")")
				.digweedPickup(true)
				.leverNumbers(Collections.emptyMap())
				.highlightVessel(false)
				.nextPotionSlot(-1)
				.next(null)
				.belt(BeltColour.NONE);
			if (b.phase() == Phase.PROCESS)
			{
				// No station outline competing with the pickup.
				b.station(null);
			}
		}
	}

	/**
	 * True while the vessel holds lever pulls: a potion is part made.
	 */
	private static boolean mixing(GuideInput in)
	{
		for (int slot : in.vesselSlots)
		{
			if (slot != 0)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Swaps the phase step's instruction for another one, keeping its belt verdict.
	 */
	private static Step.Builder takeOver(Step.Builder b, String headline)
	{
		return b.headline(headline)
			.status("")
			.make(null)
			.station(null)
			.leverNumbers(Collections.emptyMap())
			.highlightVessel(false)
			.nextPotionSlot(-1)
			.stationCount(-1)
			.digweedSlot(-1)
			.belt(BeltColour.NONE);
	}

	private static int digweedTarget(GuideInput in)
	{
		SlotMap map = in.map;
		if (in.holdDigweed)
		{
			for (int slot : map.occupiedSlots())
			{
				PotionSlot p = map.get(slot);
				if (p.type() == PotionType.MIXALOT && !p.digweed() && ordered(in.orders, p))
				{
					return slot;
				}
			}
			return -1;
		}
		for (int slot : map.occupiedSlots())
		{
			PotionSlot p = map.get(slot);
			if (p.type() == PotionType.MIXALOT && !p.digweed())
			{
				return slot;
			}
		}
		int best = -1;
		for (int slot : map.occupiedSlots())
		{
			PotionSlot p = map.get(slot);
			if (!p.digweed() && ordered(in.orders, p) && (best < 0 || p.type().xp() > map.get(best).type().xp()))
			{
				best = slot;
			}
		}
		return best;
	}

	private static boolean ordered(List<Order> orders, PotionSlot p)
	{
		for (Order o : orders)
		{
			if (o.type() == p.type() && o.station() == p.station())
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Planned cells held finished, unprocessed, or loaded into a station.
	 */
	private static int stockHave(GuideInput in)
	{
		int have = 0;
		for (PotionType type : in.plan.types())
		{
			for (Station station : Station.PROCESS_ORDER)
			{
				if (StockPlan.covered(in.map, in.inStations, new Cell(type, station)) > 0)
				{
					have++;
				}
			}
		}
		return have;
	}

	/**
	 * The fixed compass label of a digweed spot.
	 */
	static String digweedDirection(LabObject spot)
	{
		switch (spot)
		{
			case DIGWEED_NORTH_EAST:
				return "north east";
			case DIGWEED_SOUTH_EAST:
				return "south east";
			case DIGWEED_SOUTH_WEST:
				return "south west";
			case DIGWEED_NORTH_WEST:
				return "north west";
			default:
				throw new IllegalArgumentException("Not a digweed spot: " + spot);
		}
	}

	private static String stockPart(GuideInput in)
	{
		int total = in.plan.size();
		return total == 0 ? "" : "stock " + stockHave(in) + " / " + total;
	}

	private static String makeOrderHeadline(Cell cell)
	{
		return "Make " + cell.type().code() + " → " + cell.station().displayName();
	}

	private static Cell cell(Order o)
	{
		return new Cell(o.type(), o.station());
	}

	private static String join(String... parts)
	{
		StringBuilder sb = new StringBuilder();
		for (String part : parts)
		{
			if (part != null && !part.isEmpty())
			{
				if (sb.length() > 0)
				{
					sb.append(SEPARATOR);
				}
				sb.append(part);
			}
		}
		return sb.toString();
	}
}

package com.mixologybeltrunner;

import java.util.Collections;
import java.util.List;
import java.util.Map;

/**
 * Everything the guide reads, filled in by the plugin each tick.
 */
public final class GuideInput
{
	/**
	 * Name of an enabled rival plugin, or null.
	 */
	public String rival;
	/**
	 * Real Herblore level, not boosted.
	 */
	public int herbloreLevel;
	/**
	 * True below Herblore 81 until the first potion of the session is made.
	 */
	public boolean lowLevelWarning;
	public TrackerState trackerState = TrackerState.NEEDS_CLEAR;
	public String pauseReason;
	public SlotMap map = new SlotMap();
	public StockPlan plan = StockPlan.create(SlotMap.SIZE);
	public List<Order> orders = Collections.emptyList();
	/**
	 * Potions loaded into a station, still unprocessed.
	 */
	public Map<Station, PotionSlot> inStations = Collections.emptyMap();
	public int[] vesselSlots = new int[3];
	/**
	 * The potion waiting in the mixing vessel, or null.
	 */
	public PotionType vesselReady;
	public boolean digweedHeld;
	/**
	 * The spot where digweed has grown, or null.
	 */
	public LabObject digweedSpawn;
	public boolean holdDigweed;
	public int restockThreshold = 10;
	public Mode mode = Mode.FOCUS_XP;
	/**
	 * The inventory slot the next potion lands in: the lowest empty one, -1 when full.
	 */
	public int landingSlot = -1;
}

package com.mixologybeltrunner;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ProgressBarComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * The guide window: the current instruction and the stock, in the style picked in the config.
 */
public class GuideOverlay extends OverlayPanel
{
	private static final Color TITLE = new Color(0xff981f);
	private static final Color WARNING = new Color(0xffd54f);
	private static final Color FINISHED = new Color(0x4caf50);
	private static final Color UNPROCESSED = new Color(0xffd54f);
	private static final Color MISSING = new Color(0x9e9e9e);
	private static final Color STATUS = new Color(0xbdbdbd);
	private static final int WIDTH = 200;
	private static final int COLUMN_WIDTH = 36;

	private final BeltRunnerPlugin plugin;
	private final BeltRunnerConfig config;

	@Inject
	GuideOverlay(BeltRunnerPlugin plugin, BeltRunnerConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Step step = plugin.currentStep();
		if (step == null || !plugin.inLab())
		{
			return null;
		}
		panelComponent.setPreferredSize(new Dimension(WIDTH, 0));
		panelComponent.getChildren().add(TitleComponent.builder().text("Belt Runner").color(TITLE).build());
		if (!step.warning().isEmpty())
		{
			panelComponent.getChildren().add(SegmentLine.wrapped(FontManager.getRunescapeSmallFont(), step.warning(), WARNING));
		}
		if (step.phase() == Phase.DORMANT || step.phase() == Phase.NEEDS_CLEAR)
		{
			addHeadline(step);
			addStatus(step);
		}
		else
		{
			switch (config.windowStyle())
			{
				case TODO_LIST:
					addHeadline(step);
					addTodo(step.rows());
					break;
				case FULL_GRID:
					addHeadline(step);
					addGrid(step.rows());
					break;
				default:
					addStatus(step);
					addHeadline(step);
					addStockBar(step);
					break;
			}
		}
		return super.render(graphics);
	}

	private void addStatus(Step step)
	{
		if (!step.status().isEmpty())
		{
			panelComponent.getChildren().add(SegmentLine.wrapped(FontManager.getRunescapeSmallFont(), step.status(), STATUS));
		}
	}

	private void addHeadline(Step step)
	{
		panelComponent.getChildren().add(SegmentLine.wrapped(FontManager.getRunescapeBoldFont(), step.headline(), Color.WHITE));
	}

	private void addStockBar(Step step)
	{
		if (step.stockTotal() == 0)
		{
			return;
		}
		ProgressBarComponent bar = new ProgressBarComponent();
		bar.setMinimum(0);
		bar.setMaximum(step.stockTotal());
		bar.setValue(step.stockHave());
		bar.setLabelDisplayMode(ProgressBarComponent.LabelDisplayMode.FULL);
		bar.setForegroundColor(FINISHED);
		bar.setBackgroundColor(new Color(0x303030));
		panelComponent.getChildren().add(bar);
	}

	private void addTodo(List<StockSummary.Row> rows)
	{
		List<TodoLines.Make> make = TodoLines.toMake(rows);
		if (!make.isEmpty())
		{
			addSubtitle("To make");
			for (TodoLines.Make m : make)
			{
				SegmentLine line = new SegmentLine(FontManager.getRunescapeSmallFont())
					.leftCode(m.type())
					.left(" ×" + m.count(), Color.WHITE)
					.right(stationNames(m.stations()), STATUS);
				panelComponent.getChildren().add(line);
			}
		}
		Map<Station, List<PotionType>> process = TodoLines.toProcess(rows);
		if (!process.isEmpty())
		{
			addSubtitle("To process");
			for (Map.Entry<Station, List<PotionType>> e : process.entrySet())
			{
				StringBuilder codes = new StringBuilder();
				for (PotionType type : e.getValue())
				{
					if (codes.length() > 0)
					{
						codes.append(' ');
					}
					codes.append(type.code());
				}
				SegmentLine line = new SegmentLine(FontManager.getRunescapeSmallFont())
					.left(e.getKey().displayName() + " ×" + e.getValue().size(), Color.WHITE)
					.right(codes.toString(), UNPROCESSED);
				panelComponent.getChildren().add(line);
			}
		}
	}

	private void addSubtitle(String text)
	{
		panelComponent.getChildren().add(new SegmentLine(FontManager.getRunescapeSmallFont()).left(text, TITLE));
	}

	private static String stationNames(List<Station> stations)
	{
		StringBuilder sb = new StringBuilder();
		for (Station s : stations)
		{
			if (sb.length() > 0)
			{
				sb.append(' ');
			}
			sb.append(s.shortName());
		}
		return sb.toString();
	}

	private void addGrid(List<StockSummary.Row> rows)
	{
		SegmentLine header = new SegmentLine(FontManager.getRunescapeSmallFont());
		for (Station station : Station.PROCESS_ORDER)
		{
			header.cell(station.shortName(), STATUS, columnCentre(station));
		}
		panelComponent.getChildren().add(header);
		for (StockSummary.Row row : rows)
		{
			SegmentLine line = new SegmentLine(FontManager.getRunescapeSmallFont()).leftCode(row.type());
			for (Station station : Station.PROCESS_ORDER)
			{
				boolean digweed = row.digweed(station);
				line.cell(glyph(row.state(station), digweed), digweed ? config.digweedColour() : stateColour(row.state(station)), columnCentre(station));
			}
			panelComponent.getChildren().add(line);
		}
	}

	private static int columnCentre(Station station)
	{
		return COLUMN_WIDTH / 2 + (Station.PROCESS_ORDER.size() - 1 - station.ordinal()) * COLUMN_WIDTH;
	}

	private static String glyph(CellState state, boolean digweed)
	{
		if (digweed)
		{
			return "★";
		}
		switch (state)
		{
			case FINISHED:
				return "✓";
			case UNPROCESSED:
				return "○";
			default:
				return "·";
		}
	}

	private static Color stateColour(CellState state)
	{
		switch (state)
		{
			case FINISHED:
				return FINISHED;
			case UNPROCESSED:
				return UNPROCESSED;
			default:
				return MISSING;
		}
	}
}

package com.mixologybeltrunner;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.ImageUtil;

/**
 * Outlines the potion the station takes next and, while digweed is to be used, the digweed
 * and the potion it goes on, tinted as well so the pair stands out.
 */
public class InventoryOverlay extends WidgetItemOverlay
{
	private final BeltRunnerPlugin plugin;
	private final BeltRunnerConfig config;
	private final ItemManager itemManager;

	@Inject
	InventoryOverlay(BeltRunnerPlugin plugin, BeltRunnerConfig config, ItemManager itemManager)
	{
		this.plugin = plugin;
		this.config = config;
		this.itemManager = itemManager;
		showOnInventory();
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		Step step = plugin.currentStep();
		if (step == null || !plugin.inLab())
		{
			return;
		}
		Widget widget = widgetItem.getWidget();
		if (widget == null)
		{
			return;
		}
		int slot = widget.getIndex();
		boolean usingDigweed = step.digweedSlot() >= 0;
		if (slot == step.digweedSlot() || usingDigweed && itemId == ItemID.MM_LAB_SPECIAL_HERB)
		{
			drawFilled(graphics, itemId, widgetItem, config.digweedColour());
		}
		else if (slot == step.nextPotionSlot())
		{
			draw(graphics, itemId, widgetItem, Color.WHITE);
		}
	}

	/**
	 * The outline plus a light wash of the same colour over the item, the way Quest Helper does it.
	 */
	private void drawFilled(Graphics2D graphics, int itemId, WidgetItem widgetItem, Color colour)
	{
		draw(graphics, itemId, widgetItem, colour);
		Image tint = ImageUtil.fillImage(itemManager.getImage(itemId, widgetItem.getQuantity(), false),
			ColorUtil.colorWithAlpha(colour, 65));
		graphics.drawImage(tint, widgetItem.getCanvasBounds().x, widgetItem.getCanvasBounds().y, null);
	}

	private void draw(Graphics2D graphics, int itemId, WidgetItem widgetItem, Color colour)
	{
		BufferedImage outline = itemManager.getItemOutline(itemId, widgetItem.getQuantity(), colour);
		graphics.drawImage(outline, widgetItem.getCanvasBounds().x, widgetItem.getCanvasBounds().y, null);
	}
}

package com.mixologybeltrunner;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.gameval.ItemID;

/**
 * Follows each potion by inventory slot, so the plugin knows which station a
 * finished potion went through. The item id does not say, and the game keeps no
 * client-side record of it.
 * <p>
 * Inventory snapshots are compared against the slot map. A changed slot has to be
 * explained by an event (a station loading or clearing, a deposit, a failed deposit,
 * a drop, a drag);
 * either side may arrive first. A change nothing explains within {@link #GRACE_TICKS}
 * stops tracking until the inventory is cleared of potions. The tracker never guesses.
 */
@Slf4j
public final class InventoryTracker
{
	/**
	 * Picks the planned station for a potion that has just come out of the vessel.
	 */
	public interface StationAssigner
	{
		Station assign(SlotMap map, Map<Station, PotionSlot> inStations, PotionType type);
	}

	/**
	 * How long a slot may stay unexplained before tracking stops.
	 */
	static final int GRACE_TICKS = 2;
	/**
	 * How long after the last belt click finished potions may leave as deposits.
	 */
	static final int DEPOSIT_TICKS = 20;
	/**
	 * How long a drop or destroy click waits; destroy asks for confirmation first.
	 */
	static final int DROP_TICKS = 50;
	/**
	 * How long station, failed deposit and digweed events wait for their inventory change.
	 */
	static final int EVENT_TICKS = 5;

	private static final int NONE = Integer.MIN_VALUE;
	private static final int UNSTAMPED = Integer.MIN_VALUE + 1;
	private static final int DIGWEED = ItemID.MM_LAB_SPECIAL_HERB;

	private static final String NOT_STARTED = "Tracking has not started.";
	private static final String HELD_AT_START = "Potions were already in the inventory when tracking started.";
	private static final String FAILED_DEPOSIT_MISMATCH = "The belt took a potion the tracker did not expect.";

	/**
	 * A one-sided event waiting for the inventory change it explains. Events carry
	 * no tick of their own, so each is stamped by the next tick the tracker sees.
	 */
	private static final class Pending
	{
		/**
		 * Load: what went in. Clear: what is coming out. Null for the rest.
		 */
		private final PotionSlot entry;
		/**
		 * Load: the first unprocessed slot when it went in. Failed deposit: the first
		 * finished slot when the game named it. Drop, digweed: the clicked slot. Follows
		 * drags.
		 */
		private int slot;
		private int tick = UNSTAMPED;

		private Pending(PotionSlot entry, int slot)
		{
			this.entry = entry;
			this.slot = slot;
		}
	}

	private final StationAssigner assigner;

	private SlotMap map = new SlotMap();
	private final Map<Station, PotionSlot> stations = new EnumMap<>(Station.class);
	/**
	 * The last inventory seen, with known drags already applied.
	 */
	private int[] lastIds = emptyInventory();
	/**
	 * Tick each slot first disagreed with the map, or NONE.
	 */
	private final int[] firstSeen = new int[SlotMap.SIZE];

	private final List<Pending> loads = new ArrayList<>();
	private final List<Pending> clears = new ArrayList<>();
	private final List<Pending> drops = new ArrayList<>();
	private final List<Pending> digweeds = new ArrayList<>();
	/**
	 * Each belongs to one inventory change: dropped once a change is reconciled
	 * without it, or straight away if its change already came this tick.
	 */
	private final List<Pending> failedDeposits = new ArrayList<>();
	/**
	 * True from an inventory change until the next tick.
	 */
	private boolean changedThisTick;
	/**
	 * True when an order claimed a finished potion this tick, so a failed deposit that
	 * arrives after its inventory change can see the contradiction.
	 */
	private boolean claimedThisTick;
	/**
	 * The order board as last passed in; each deposit is claimed against the board
	 * live when its inventory change arrives.
	 */
	private List<Order> orders = Collections.emptyList();
	/**
	 * True from a belt click until {@link #DEPOSIT_TICKS} after the last one.
	 */
	private boolean depositArmed;
	private int depositTick;

	private TrackerState state = TrackerState.NEEDS_CLEAR;
	private String pauseReason = NOT_STARTED;
	private boolean pauseEvent;
	private int revision;
	private int lastTick = UNSTAMPED;

	public InventoryTracker(StationAssigner assigner)
	{
		this.assigner = assigner;
		Arrays.fill(firstSeen, NONE);
	}

	/**
	 * Starts fresh. Tracks only if the inventory holds no mixology potion, since
	 * potions already there have an unknown history.
	 */
	public void start(int[] inventoryIds, Map<Station, PotionType> loadedStations)
	{
		begin(inventoryIds, loadedStations);
		if (hasPotion(lastIds))
		{
			state = TrackerState.NEEDS_CLEAR;
			pauseReason = HELD_AT_START;
		}
		else
		{
			state = TrackerState.TRACKING;
			pauseReason = null;
		}
	}

	/**
	 * Picks up a saved map if it still matches the inventory slot for slot,
	 * otherwise starts fresh.
	 */
	public void restore(SlotMap saved, int[] inventoryIds, Map<Station, PotionType> loadedStations)
	{
		int[] ids = normalise(inventoryIds);
		if (saved == null || !Arrays.equals(saved.expectedItemIds(), potionIds(ids)))
		{
			start(inventoryIds, loadedStations);
			return;
		}
		begin(inventoryIds, loadedStations);
		map = saved.copy();
		state = TrackerState.TRACKING;
		pauseReason = null;
	}

	/**
	 * A station took a potion of {@code type} (read from the station varbit). Its
	 * contents are recorded straight away, paused or not. While tracking, the load
	 * also explains the loss of the inventory's first unfinished potion if that is
	 * the same type; any other loss stays unexplained.
	 */
	public void onStationLoaded(Station s, PotionType type)
	{
		if (s == null || type == null || stations.containsKey(s))
		{
			return;
		}
		PotionSlot entry = new PotionSlot(type, false, s, false);
		stations.put(s, entry);
		if (state != TrackerState.TRACKING)
		{
			return;
		}
		int slot = map.firstUnprocessed();
		if (slot != -1 && map.get(slot).type() == type)
		{
			loads.add(new Pending(entry, slot));
			reconcile();
		}
	}

	public void onStationCleared(Station s)
	{
		PotionSlot entry = stations.remove(s);
		if (state != TrackerState.TRACKING || entry == null)
		{
			return;
		}
		clears.add(new Pending(entry, -1));
		reconcile();
	}

	/**
	 * A belt click. Every finished potion that leaves within {@link #DEPOSIT_TICKS} of the
	 * last click is explained if the board live at the time asks for it, so a double click
	 * that the game runs as two deposits, the second against a refreshed board, is followed.
	 */
	public void onDepositClick(List<Order> orders)
	{
		if (state != TrackerState.TRACKING)
		{
			return;
		}
		this.orders = new ArrayList<>(orders);
		depositArmed = true;
		depositTick = UNSTAMPED;
		reconcile();
	}

	/**
	 * The game said "You deposit some X, but fail to fulfil an order". The belt then takes
	 * the first finished potion in the inventory, so this explains one loss: the lowest
	 * slot holding a finished potion, when that potion is an X and no unclaimed order on
	 * the live board wants it. While it waits for its inventory change, no claim explains
	 * a loss. Anything else, including a claim already made this tick, means the game has
	 * contradicted the map: tracking stops at once, so no later claim can absorb the loss.
	 */
	public void onFailedDeposit(PotionType type)
	{
		if (state != TrackerState.TRACKING || type == null)
		{
			return;
		}
		int slot = firstProcessed();
		// claimedThisTick: an inventory change came first and an order claimed a potion.
		if (claimedThisTick || slot == -1 || map.get(slot).type() != type)
		{
			pause(FAILED_DEPOSIT_MISMATCH);
			return;
		}
		failedDeposits.add(new Pending(null, slot));
		reconcile();
		if (changedThisTick)
		{
			// Its inventory change came first and needed no failed deposit.
			failedDeposits.clear();
		}
	}

	public void onDropClick(int slot)
	{
		if (state != TrackerState.TRACKING || !validSlot(slot))
		{
			return;
		}
		drops.add(new Pending(null, slot));
		reconcile();
	}

	public void onDigweedUsed(int slot)
	{
		if (state != TrackerState.TRACKING || !validSlot(slot))
		{
			return;
		}
		digweeds.add(new Pending(null, slot));
	}

	/**
	 * Applies a drag at once, to the map and to the expected inventory, so the
	 * inventory change that follows (if any; identical swaps send none) matches.
	 */
	public void onDrag(int from, int to)
	{
		if (state != TrackerState.TRACKING || !validSlot(from) || !validSlot(to) || from == to)
		{
			return;
		}
		map.move(from, to);
		swap(lastIds, from, to);
		swap(firstSeen, from, to);
		followDrag(loads, from, to);
		followDrag(drops, from, to);
		followDrag(digweeds, from, to);
		followDrag(failedDeposits, from, to);
		revision++;
	}

	/**
	 * @param orders the order board live when the change arrived, which is the board any
	 *               deposit in it was made against
	 */
	public void onInventory(int[] ids, int tick, List<Order> orders)
	{
		this.orders = new ArrayList<>(orders);
		onInventory(ids, tick);
	}

	/**
	 * An inventory change with the order board unchanged since it was last passed in.
	 */
	public void onInventory(int[] ids, int tick)
	{
		stamp(tick);
		int[] next = normalise(ids);
		int digweedUsed = count(lastIds, DIGWEED) - count(next, DIGWEED);
		lastIds = next;
		if (state == TrackerState.TRACKING)
		{
			applyDigweed(digweedUsed);
			reconcile();
			failedDeposits.clear();
			changedThisTick = true;
		}
		else if (!hasPotion(next))
		{
			resume();
		}
		expire(tick);
	}

	public void onTick(int tick)
	{
		stamp(tick);
		expire(tick);
		changedThisTick = false;
		claimedThisTick = false;
		if (state != TrackerState.TRACKING)
		{
			return;
		}
		for (int slot = 0; slot < SlotMap.SIZE; slot++)
		{
			int seen = firstSeen[slot];
			if (seen != NONE && seen != UNSTAMPED && tick - seen >= GRACE_TICKS)
			{
				pause(lostTrack(slot));
				return;
			}
		}
	}

	public TrackerState state()
	{
		return state;
	}

	/**
	 * A copy of the slot map.
	 */
	public SlotMap map()
	{
		return map.copy();
	}

	public PotionSlot inStation(Station s)
	{
		return stations.get(s);
	}

	public Map<Station, PotionSlot> stationContents()
	{
		return Collections.unmodifiableMap(new EnumMap<>(stations));
	}

	public String pauseReason()
	{
		return pauseReason;
	}

	/**
	 * True once after each stop, so the plugin can warn in chat.
	 */
	public boolean consumePauseEvent()
	{
		boolean was = pauseEvent;
		pauseEvent = false;
		return was;
	}

	/**
	 * Goes up on every change to the slot map.
	 */
	public int revision()
	{
		return revision;
	}

	private void begin(int[] inventoryIds, Map<Station, PotionType> loadedStations)
	{
		clearPending();
		stations.clear();
		for (Map.Entry<Station, PotionType> e : loadedStations.entrySet())
		{
			if (e.getKey() != null && e.getValue() != null)
			{
				stations.put(e.getKey(), new PotionSlot(e.getValue(), false, e.getKey(), false));
			}
		}
		lastIds = normalise(inventoryIds);
		map = new SlotMap();
		pauseEvent = false;
		revision++;
	}

	/**
	 * Explains as many slot differences as the pending events allow. Losses go
	 * first so a slot they free can take a new potion in the same pass.
	 */
	private void reconcile()
	{
		int[] seen = potionIds(lastIds);
		boolean[] claimed = depositArmed ? new boolean[orders.size()] : null;
		// A pending failed deposit says no order took a potion in this change.
		boolean mayClaim = claimed != null && failedDeposits.isEmpty();

		for (int slot = 0; slot < SlotMap.SIZE; slot++)
		{
			PotionSlot p = map.get(slot);
			if (p == null || p.expectedItemId() == seen[slot])
			{
				continue;
			}
			Pending load;
			if (take(drops, slot) != null)
			{
				map.remove(slot);
				revision++;
			}
			else if (!p.processed() && (load = take(loads, slot)) != null)
			{
				Station s = load.entry.station();
				map.remove(slot);
				if (stations.get(s) == load.entry)
				{
					// Same potion, now with its digweed.
					stations.put(s, new PotionSlot(p.type(), false, s, p.digweed()));
				}
				revision++;
			}
			else if (p.processed() && take(failedDeposits, slot) != null)
			{
				// Ahead of the claim: the game says no order took this one.
				if (wanted(orders, claimed, p))
				{
					pause(FAILED_DEPOSIT_MISMATCH);
					return;
				}
				map.remove(slot);
				revision++;
			}
			else if (p.processed() && mayClaim && claim(orders, claimed, p))
			{
				claimedThisTick = true;
				map.remove(slot);
				revision++;
			}
		}

		for (int slot = 0; slot < SlotMap.SIZE; slot++)
		{
			if (map.get(slot) != null || seen[slot] == -1)
			{
				continue;
			}
			PotionType type = PotionType.fromItemId(seen[slot]);
			if (!type.isFinishedItem(seen[slot]))
			{
				// Unfinished potions only come from the vessel.
				map.put(slot, new PotionSlot(type, false, assigner.assign(map.copy(), stationContents(), type), false));
				revision++;
				continue;
			}
			Pending clear = onlyClearFor(type);
			if (clear != null)
			{
				clears.remove(clear);
				map.put(slot, clear.entry.processedAt(clear.entry.station()));
				revision++;
			}
		}

		int[] expected = map.expectedItemIds();
		for (int slot = 0; slot < SlotMap.SIZE; slot++)
		{
			if (expected[slot] == seen[slot])
			{
				firstSeen[slot] = NONE;
			}
			else if (firstSeen[slot] == NONE)
			{
				firstSeen[slot] = lastTick;
			}
		}
	}

	/**
	 * The pending clear a finished potion of {@code type} came from, or null when
	 * none or several match: the tracker does not pick between them.
	 */
	private Pending onlyClearFor(PotionType type)
	{
		Pending found = null;
		for (Pending c : clears)
		{
			if (c.entry.type() == type)
			{
				if (found != null)
				{
					return null;
				}
				found = c;
			}
		}
		return found;
	}

	/**
	 * The lowest slot in the map holding a finished potion, or -1.
	 */
	private int firstProcessed()
	{
		for (int slot = 0; slot < SlotMap.SIZE; slot++)
		{
			PotionSlot p = map.get(slot);
			if (p != null && p.processed())
			{
				return slot;
			}
		}
		return -1;
	}

	/**
	 * True when an order not yet claimed in this pass asks for {@code p}.
	 */
	private static boolean wanted(List<Order> orders, boolean[] claimed, PotionSlot p)
	{
		for (int i = 0; i < orders.size(); i++)
		{
			Order o = orders.get(i);
			if ((claimed == null || !claimed[i]) && o.type() == p.type() && o.station() == p.station())
			{
				return true;
			}
		}
		return false;
	}

	private static String lostTrack(int slot)
	{
		return "Lost track of the potion in inventory slot " + (slot + 1) + ".";
	}

	private static boolean claim(List<Order> orders, boolean[] claimed, PotionSlot p)
	{
		for (int i = 0; i < orders.size(); i++)
		{
			Order o = orders.get(i);
			if (!claimed[i] && o.type() == p.type() && o.station() == p.station())
			{
				claimed[i] = true;
				return true;
			}
		}
		return false;
	}

	private void applyDigweed(int used)
	{
		for (int i = 0; i < used && !digweeds.isEmpty(); i++)
		{
			int slot = digweeds.remove(0).slot;
			PotionSlot p = map.get(slot);
			if (p != null)
			{
				map.put(slot, p.withDigweed());
				revision++;
			}
		}
	}

	private void pause(String reason)
	{
		log.debug("Tracking paused: {}", reason);
		state = TrackerState.NEEDS_CLEAR;
		pauseReason = reason;
		pauseEvent = true;
		map = new SlotMap();
		clearPending();
		revision++;
	}

	private void resume()
	{
		state = TrackerState.TRACKING;
		pauseReason = null;
		map = new SlotMap();
		clearPending();
		revision++;
	}

	/**
	 * Drops pending events and unexplained slots. Known station contents stay:
	 * the game has not touched them.
	 */
	private void clearPending()
	{
		loads.clear();
		clears.clear();
		drops.clear();
		digweeds.clear();
		failedDeposits.clear();
		claimedThisTick = false;
		depositArmed = false;
		Arrays.fill(firstSeen, NONE);
	}

	private void stamp(int tick)
	{
		lastTick = tick;
		stampAll(loads, tick);
		stampAll(clears, tick);
		stampAll(drops, tick);
		stampAll(digweeds, tick);
		stampAll(failedDeposits, tick);
		if (depositArmed && depositTick == UNSTAMPED)
		{
			depositTick = tick;
		}
		for (int slot = 0; slot < SlotMap.SIZE; slot++)
		{
			if (firstSeen[slot] == UNSTAMPED)
			{
				firstSeen[slot] = tick;
			}
		}
	}

	private void expire(int tick)
	{
		expireAll(loads, tick, EVENT_TICKS);
		expireAll(digweeds, tick, EVENT_TICKS);
		expireAll(clears, tick, EVENT_TICKS);
		expireAll(failedDeposits, tick, EVENT_TICKS);
		expireAll(drops, tick, DROP_TICKS);
		if (depositArmed && expired(depositTick, tick, DEPOSIT_TICKS))
		{
			depositArmed = false;
		}
	}

	private static void stampAll(List<Pending> list, int tick)
	{
		for (Pending p : list)
		{
			if (p.tick == UNSTAMPED)
			{
				p.tick = tick;
			}
		}
	}

	private static void expireAll(List<Pending> list, int tick, int window)
	{
		list.removeIf(p -> expired(p.tick, tick, window));
	}

	private static boolean expired(int stamped, int tick, int window)
	{
		return stamped != UNSTAMPED && tick - stamped > window;
	}

	/**
	 * Removes and returns the first pending event pointing at {@code slot}, or null.
	 */
	private static Pending take(List<Pending> list, int slot)
	{
		for (Iterator<Pending> it = list.iterator(); it.hasNext(); )
		{
			Pending p = it.next();
			if (p.slot == slot)
			{
				it.remove();
				return p;
			}
		}
		return null;
	}

	private static void followDrag(List<Pending> list, int from, int to)
	{
		for (Pending p : list)
		{
			if (p.slot == from)
			{
				p.slot = to;
			}
			else if (p.slot == to)
			{
				p.slot = from;
			}
		}
	}

	private static int[] emptyInventory()
	{
		int[] ids = new int[SlotMap.SIZE];
		Arrays.fill(ids, -1);
		return ids;
	}

	/**
	 * Pads or trims to 28 slots; the client's array can be shorter than the inventory.
	 */
	private static int[] normalise(int[] ids)
	{
		int[] out = emptyInventory();
		if (ids != null)
		{
			System.arraycopy(ids, 0, out, 0, Math.min(ids.length, SlotMap.SIZE));
		}
		return out;
	}

	/**
	 * Potion ids per slot; anything that is not a mixology potion becomes -1.
	 */
	private static int[] potionIds(int[] ids)
	{
		int[] out = new int[SlotMap.SIZE];
		for (int i = 0; i < SlotMap.SIZE; i++)
		{
			out[i] = PotionType.fromItemId(ids[i]) == null ? -1 : ids[i];
		}
		return out;
	}

	private static boolean hasPotion(int[] ids)
	{
		for (int id : ids)
		{
			if (PotionType.fromItemId(id) != null)
			{
				return true;
			}
		}
		return false;
	}

	private static int count(int[] ids, int itemId)
	{
		int n = 0;
		for (int id : ids)
		{
			if (id == itemId)
			{
				n++;
			}
		}
		return n;
	}

	private static boolean validSlot(int slot)
	{
		return slot >= 0 && slot < SlotMap.SIZE;
	}

	private static void swap(int[] a, int i, int j)
	{
		int tmp = a[i];
		a[i] = a[j];
		a[j] = tmp;
	}
}

package com.mixologybeltrunner;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.font.TextLayout;
import java.awt.geom.AffineTransform;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Text drawn in the scene: the pull numbers over the levers, the potion being made by the
 * vessel, the countdown over the station being worked and "Deposit" over the belt. Drawn on
 * the top layer, large and outlined. Each label goes to the far side of its object from the
 * player when it first appears and stays there while it is shown, so it never sits over the
 * character and does not drift as they walk.
 */
class LabLabelsOverlay extends Overlay
{
	private static final int HEIGHT = 150;
	private static final float SIZE = 24f;
	private static final float NEXT_SIZE = 18f;
	private static final BasicStroke OUTLINE = new BasicStroke(4f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);
	/**
	 * How far past the object the label sits, in local units (128 per tile).
	 */
	static final int AWAY = 176;
	/**
	 * Beyond this distance from the object (local units) the label stays over the object.
	 */
	static final int NEAR = 128 * 12;

	private final Client client;
	private final BeltRunnerPlugin plugin;
	private final BeltRunnerConfig config;
	/**
	 * Where each shown label sits, fixed when it first appears.
	 */
	private final Map<WorldPoint, int[]> anchors = new HashMap<>();
	private final Set<WorldPoint> shown = new HashSet<>();

	@Inject
	LabLabelsOverlay(Client client, BeltRunnerPlugin plugin, BeltRunnerConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Step step = plugin.currentStep();
		WorldView worldView = client.getTopLevelWorldView();
		if (step == null || !plugin.inLab() || worldView == null)
		{
			anchors.clear();
			return null;
		}
		shown.clear();
		graphics.setFont(FontManager.getRunescapeBoldFont().deriveFont(SIZE));
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		LocalPoint player = playerPoint(worldView);

		for (Map.Entry<PotionComponent, List<Integer>> entry : step.leverNumbers().entrySet())
		{
			String text = LabOverlay.leverLabel(step.leverNumbers(), entry.getKey());
			label(graphics, worldView, player, LabOverlay.leverFor(entry.getKey()).coordinate(), segments(text, entry.getKey().color()));
		}
		if (step.phase() == Phase.MAKE && step.make() != null && !step.leverNumbers().isEmpty())
		{
			label(graphics, worldView, player, LabObject.MIXING_VESSEL.coordinate(), makeLabel(step.make()));
		}

		String count = stationLabel(step);
		if (count != null)
		{
			label(graphics, worldView, player, step.station().object().coordinate(), segments(count, Color.WHITE));
		}
		if (step.belt() == BeltColour.GREEN)
		{
			label(graphics, worldView, player, LabObject.CONVEYOR_BELT.coordinate(), segments("Deposit", config.beltOpenColour()));
		}
		if (step.digweedPickup() && step.digweedSpot() != null)
		{
			label(graphics, worldView, player, step.digweedSpot().coordinate(), segments("Pick up", config.digweedColour()));
		}
		LabObject next = LabOverlay.nextToOutline(step);
		if (next != null)
		{
			graphics.setFont(FontManager.getRunescapeBoldFont().deriveFont(NEXT_SIZE));
			label(graphics, worldView, player, next.coordinate(), segments("Next", Color.WHITE));
			graphics.setFont(FontManager.getRunescapeBoldFont().deriveFont(SIZE));
		}
		if (step.digweedTarget() != null)
		{
			overhead(graphics, digweedLabel(step.digweedTarget(), config.digweedColour()));
		}
		anchors.keySet().retainAll(shown);
		return null;
	}

	/**
	 * "Make 7" counting down while potions are still to go into the station, "Last one" once
	 * the potion inside is the last; null when the step has no station count.
	 */
	static String stationLabel(Step step)
	{
		if (step.phase() != Phase.PROCESS || step.station() == null || step.stationCount() < 0)
		{
			return null;
		}
		return step.stationCount() > 0 ? "Make " + step.stationCount() : "Last one";
	}

	/**
	 * "Digweed → " in the digweed colour followed by the potion code in its paste colours.
	 */
	static List<Segment> digweedLabel(PotionType type, Color digweed)
	{
		List<Segment> out = new ArrayList<>();
		out.add(new Segment("Digweed → ", digweed));
		for (PotionComponent component : type.components())
		{
			out.add(new Segment(String.valueOf(component.letter()), component.color()));
		}
		return out;
	}

	/**
	 * "Make " in white followed by the potion code, each letter in its paste colour.
	 */
	static List<Segment> makeLabel(PotionType type)
	{
		List<Segment> out = new ArrayList<>();
		out.add(new Segment("Make ", Color.WHITE));
		for (PotionComponent component : type.components())
		{
			out.add(new Segment(String.valueOf(component.letter()), component.color()));
		}
		return out;
	}

	private static List<Segment> segments(String text, Color colour)
	{
		List<Segment> out = new ArrayList<>();
		if (text != null)
		{
			out.add(new Segment(text, colour));
		}
		return out;
	}

	/**
	 * A run of label text in one colour.
	 */
	static final class Segment
	{
		final String text;
		final Color colour;

		Segment(String text, Color colour)
		{
			this.text = text;
			this.colour = colour;
		}
	}

	/**
	 * The offset (local units) that moves a label from the object to its far side from the
	 * player; zero when the player stands on it or is far away.
	 */
	static int[] awayOffset(int objectX, int objectY, int playerX, int playerY)
	{
		int dx = objectX - playerX;
		int dy = objectY - playerY;
		double length = Math.hypot(dx, dy);
		if (length < 1 || length > NEAR)
		{
			return new int[]{0, 0};
		}
		return new int[]{(int) Math.round(dx / length * AWAY), (int) Math.round(dy / length * AWAY)};
	}

	private LocalPoint playerPoint(WorldView worldView)
	{
		Player player = client.getLocalPlayer();
		return player == null ? null : player.getLocalLocation();
	}

	/**
	 * A label above the player's head, for actions done in the inventory.
	 */
	private void overhead(Graphics2D graphics, List<Segment> parts)
	{
		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return;
		}
		StringBuilder whole = new StringBuilder();
		for (Segment part : parts)
		{
			whole.append(part.text);
		}
		Point location = player.getCanvasTextLocation(graphics, whole.toString(), player.getLogicalHeight() + 60);
		if (location != null)
		{
			drawSegments(graphics, parts, location);
		}
	}

	private void label(Graphics2D graphics, WorldView worldView, LocalPoint player, WorldPoint tile, List<Segment> parts)
	{
		if (parts.isEmpty())
		{
			return;
		}
		LocalPoint object = LocalPoint.fromWorld(worldView, tile);
		if (object == null)
		{
			return;
		}
		shown.add(tile);
		int[] offset = anchors.computeIfAbsent(tile, t -> player == null
			? new int[]{0, 0}
			: awayOffset(object.getX(), object.getY(), player.getX(), player.getY()));
		LocalPoint anchor = new LocalPoint(object.getX() + offset[0], object.getY() + offset[1], worldView);
		StringBuilder whole = new StringBuilder();
		for (Segment part : parts)
		{
			whole.append(part.text);
		}
		Point location = Perspective.getCanvasTextLocation(client, graphics, anchor, whole.toString(), HEIGHT);
		if (location == null)
		{
			return;
		}
		drawSegments(graphics, parts, location);
	}

	private static void drawSegments(Graphics2D graphics, List<Segment> parts, Point location)
	{
		float x = location.getX();
		for (Segment part : parts)
		{
			TextLayout layout = new TextLayout(part.text, graphics.getFont(), graphics.getFontRenderContext());
			Shape shape = layout.getOutline(AffineTransform.getTranslateInstance(x, location.getY()));
			graphics.setStroke(OUTLINE);
			graphics.setColor(Color.BLACK);
			graphics.draw(shape);
			graphics.setColor(part.colour);
			graphics.fill(shape);
			x += layout.getAdvance();
		}
	}
}

