package com.mixologybeltrunner;

import net.runelite.api.Client;
import net.runelite.api.DecorativeObject;
import net.runelite.api.GameObject;
import net.runelite.api.Scene;
import net.runelite.api.Tile;
import net.runelite.api.TileObject;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;

/**
 * Finds the scene object behind a {@link LabObject}. Client thread only.
 */
final class LabObjects
{
	private LabObjects()
	{
	}

	/**
	 * Looks on the object's tile for a game object, then a decorative object (the Aga lever is one), or null.
	 */
	static TileObject find(Client client, LabObject object)
	{
		WorldView worldView = client.getTopLevelWorldView();
		if (worldView == null)
		{
			return null;
		}
		LocalPoint point = LocalPoint.fromWorld(worldView, object.coordinate());
		if (point == null)
		{
			return null;
		}
		Scene scene = worldView.getScene();
		Tile[][][] tiles = scene.getTiles();
		Tile tile = tiles[worldView.getPlane()][point.getSceneX()][point.getSceneY()];
		if (tile == null)
		{
			return null;
		}
		for (GameObject gameObject : tile.getGameObjects())
		{
			if (gameObject != null && gameObject.getId() == object.objectId())
			{
				return gameObject;
			}
		}
		DecorativeObject decorative = tile.getDecorativeObject();
		if (decorative != null && decorative.getId() == object.objectId())
		{
			return decorative;
		}
		return null;
	}
}

package com.mixologybeltrunner;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.TileObject;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

/**
 * Outlines the lab objects the current step points at.
 */
public class LabOverlay extends Overlay
{
	private static final int OUTLINE_WIDTH = 4;
	private static final int NEXT_WIDTH = 1;
	private static final Color NEXT_COLOUR = new Color(255, 255, 255, 170);
	private static final int FEATHER = 4;
	private static final int SPOT_ALPHA = 80;

	private final Client client;
	private final BeltRunnerPlugin plugin;
	private final BeltRunnerConfig config;
	private final ModelOutlineRenderer outliner;

	@Inject
	LabOverlay(Client client, BeltRunnerPlugin plugin, BeltRunnerConfig config, ModelOutlineRenderer outliner)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.outliner = outliner;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Step step = plugin.currentStep();
		if (step == null || !plugin.inLab())
		{
			return null;
		}
		LabObject station = stationToOutline(step);
		if (station != null)
		{
			outline(station, stationColour(step.station(), plugin.quickActionStation(),
				config.highlightColour(), config.quickActionColour()));
		}
		LabObject next = nextToOutline(step);
		if (next != null)
		{
			outline(next, NEXT_COLOUR, NEXT_WIDTH);
		}
		// Only the levers this potion still needs; their numbers are drawn by LabLabelsOverlay.
		for (PotionComponent component : step.leverNumbers().keySet())
		{
			outline(leverFor(component), component.color());
		}
		if (step.highlightVessel())
		{
			outline(LabObject.MIXING_VESSEL, config.highlightColour());
		}
		if (step.belt() == BeltColour.GREEN)
		{
			outline(LabObject.CONVEYOR_BELT, config.beltOpenColour());
		}
		if (step.digweedSpot() != null)
		{
			outline(step.digweedSpot(), config.digweedColour());
			drawSpot(graphics, step.digweedSpot().coordinate(), config.digweedColour());
		}
		return null;
	}

	/**
	 * The station to outline: only while processing. Make steps carry a station too, but
	 * there the player is pointed at the levers instead.
	 */
	static LabObject stationToOutline(Step step)
	{
		return step.phase() == Phase.PROCESS && step.station() != null ? step.station().object() : null;
	}

	/**
	 * Where the player goes next, outlined thinly: only while processing, never while mixing.
	 */
	static LabObject nextToOutline(Step step)
	{
		return step.phase() == Phase.PROCESS ? step.next() : null;
	}

	/**
	 * The lever's numbers joined by spaces, or null when it has none.
	 */
	static String leverLabel(Map<PotionComponent, List<Integer>> numbers, PotionComponent component)
	{
		List<Integer> list = numbers.get(component);
		if (list == null || list.isEmpty())
		{
			return null;
		}
		StringBuilder text = new StringBuilder();
		for (int number : list)
		{
			if (text.length() > 0)
			{
				text.append(' ');
			}
			text.append(number);
		}
		return text.toString();
	}

	/**
	 * The bonus colour while the station is the one to click for the bonus, else the normal one.
	 */
	static Color stationColour(Station station, Station bonusStation, Color normal, Color bonus)
	{
		return station != null && station == bonusStation ? bonus : normal;
	}

	static LabObject leverFor(PotionComponent component)
	{
		switch (component)
		{
			case MOX:
				return LabObject.MOX_LEVER;
			case AGA:
				return LabObject.AGA_LEVER;
			default:
				return LabObject.LYE_LEVER;
		}
	}

	private void outline(LabObject object, Color colour)
	{
		outline(object, colour, OUTLINE_WIDTH);
	}

	private void outline(LabObject object, Color colour, int width)
	{
		TileObject found = LabObjects.find(client, object);
		if (found != null)
		{
			outliner.drawOutline(found, width, colour, FEATHER);
		}
	}

	private void drawSpot(Graphics2D graphics, WorldPoint tile, Color colour)
	{
		Polygon polygon = tilePolygon(tile);
		if (polygon != null)
		{
			OverlayUtil.renderPolygon(graphics, polygon, colour, withAlpha(colour, SPOT_ALPHA),
				new java.awt.BasicStroke(2));
		}
	}

	private Polygon tilePolygon(WorldPoint tile)
	{
		WorldView worldView = client.getTopLevelWorldView();
		LocalPoint point = worldView == null ? null : LocalPoint.fromWorld(worldView, tile);
		return point == null ? null : Perspective.getCanvasTilePoly(client, point);
	}

	private static Color withAlpha(Color colour, int alpha)
	{
		return new Color(colour.getRed(), colour.getGreen(), colour.getBlue(), alpha);
	}
}

package com.mixologybeltrunner;

/**
 * What the guide plays for. Both stock finished potions and restock early; they differ in how
 * many types they stock and which unfilled orders are worth making before clicking the belt.
 */
public enum Mode
{
	/**
	 * The five best potions in stock, and the belt is clicked whenever anything fills: a new
	 * set of orders costs a tick or two, making a potion for an old one costs far more.
	 */
	FOCUS_XP("Focus XP", 5, Integer.MAX_VALUE),
	/**
	 * All seven non-triples in stock, so resin comes in evenly, and an unfilled Anti-leech
	 * lotion or Mixalot order is made before the belt is clicked. Gives up a few percent of
	 * XP for more resin.
	 */
	BALANCED("Balanced", 7, 3400);

	private final String label;
	private final int stockTypes;
	private final int makeFromXp;

	Mode(String label, int stockTypes, int makeFromXp)
	{
		this.label = label;
		this.stockTypes = stockTypes;
		this.makeFromXp = makeFromXp;
	}

	/**
	 * How many non-triple types to keep in stock, best first.
	 */
	public int stockTypes()
	{
		return stockTypes;
	}

	/**
	 * True when an unfilled order for this potion is worth making before clicking the belt.
	 */
	public boolean worthMaking(PotionType type)
	{
		return type.xp() >= makeFromXp;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.mixologybeltrunner;

import java.util.Objects;

public final class Order
{
	private final int boardIndex;
	private final PotionType type;
	private final Station station;

	public Order(int boardIndex, PotionType type, Station station)
	{
		this.boardIndex = boardIndex;
		this.type = type;
		this.station = station;
	}

	public int boardIndex()
	{
		return boardIndex;
	}

	public PotionType type()
	{
		return type;
	}

	public Station station()
	{
		return station;
	}

	@Override
	public boolean equals(Object o)
	{
		if (this == o)
		{
			return true;
		}
		if (!(o instanceof Order))
		{
			return false;
		}
		Order other = (Order) o;
		return boardIndex == other.boardIndex && type == other.type && station == other.station;
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(boardIndex, type, station);
	}

	@Override
	public String toString()
	{
		return "Order[" + boardIndex + ", " + type + ", " + station + "]";
	}
}

package com.mixologybeltrunner;

/**
 * Where the path to the next destination is drawn. Click highlights are separate and stay on.
 */
public enum PathDisplay
{
	FLOOR_AND_MINIMAP("Floor & minimap"),
	FLOOR("Floor only"),
	MINIMAP("Minimap only"),
	OFF("Off");

	private final String label;

	PathDisplay(String label)
	{
		this.label = label;
	}

	public boolean showsFloor()
	{
		return this == FLOOR_AND_MINIMAP || this == FLOOR;
	}

	public boolean showsMinimap()
	{
		return this == FLOOR_AND_MINIMAP || this == MINIMAP;
	}

	public boolean isOff()
	{
		return this == OFF;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.mixologybeltrunner;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.Stroke;
import java.awt.geom.Path2D;
import java.util.List;
import java.util.function.Function;
import net.runelite.api.Point;
import net.runelite.api.coords.WorldPoint;

/**
 * The path line shared by the floor and minimap overlays; only the projection and stroke widths differ.
 */
final class PathLine
{
	private static final Color OUTLINE = new Color(0, 0, 0, 140);
	private static final int LINE_ALPHA = 220;

	private PathLine()
	{
	}

	/**
	 * Joins the projected tiles into one line, starting at the player. The tile the player is standing
	 * on is skipped, and a tile that cannot be projected breaks the line rather than bridging the gap.
	 * Returns null when nothing could be projected.
	 */
	static Path2D.Float build(List<WorldPoint> path, WorldPoint here, Point start, Function<WorldPoint, Point> project)
	{
		Path2D.Float line = new Path2D.Float();
		boolean started = false;
		if (start != null)
		{
			line.moveTo(start.getX(), start.getY());
			started = true;
		}
		boolean pendingGap = false;
		for (int i = 0; i < path.size(); i++)
		{
			WorldPoint tile = path.get(i);
			if (i == 0 && here != null && tile.distanceTo(here) <= 1 && path.size() > 1)
			{
				continue;
			}
			Point point = project.apply(tile);
			if (point == null)
			{
				pendingGap = true;
				continue;
			}
			if (!started || pendingGap)
			{
				line.moveTo(point.getX(), point.getY());
				started = true;
			}
			else
			{
				line.lineTo(point.getX(), point.getY());
			}
			pendingGap = false;
		}
		return started ? line : null;
	}

	/** A dark outline under the coloured line, anti-aliased, leaving the graphics state as it found it. */
	static void draw(Graphics2D graphics, Shape line, Stroke outline, Stroke stroke, Color base)
	{
		Stroke oldStroke = graphics.getStroke();
		Object oldHint = graphics.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		graphics.setStroke(outline);
		graphics.setColor(OUTLINE);
		graphics.draw(line);
		graphics.setStroke(stroke);
		graphics.setColor(new Color(base.getRed(), base.getGreen(), base.getBlue(), LINE_ALPHA));
		graphics.draw(line);
		graphics.setStroke(oldStroke);
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
			oldHint != null ? oldHint : RenderingHints.VALUE_ANTIALIAS_OFF);
	}
}

package com.mixologybeltrunner;

import java.awt.BasicStroke;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Shape;
import java.awt.Stroke;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * The walking path drawn on the minimap.
 */
class PathMinimapOverlay extends Overlay
{
	private static final int MINIMAP_RANGE = 6400;
	/** RuneLite's zoom-aware minimap range works out at 80 pixels; a little less stays inside the frame. */
	private static final float MINIMAP_CLIP_RADIUS = 76f;
	private static final Stroke PATH_OUTLINE = new BasicStroke(4f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);
	private static final Stroke PATH_LINE = new BasicStroke(2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);

	private final Client client;
	private final BeltRunnerConfig config;
	private final BeltRunnerPlugin plugin;

	@Inject
	PathMinimapOverlay(Client client, BeltRunnerConfig config, BeltRunnerPlugin plugin)
	{
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(Overlay.PRIORITY_LOW);
		this.client = client;
		this.config = config;
		this.plugin = plugin;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		List<WorldPoint> path = plugin.currentPath();
		if (!config.pathDisplay().showsMinimap() || !plugin.inLab() || path.size() < 2)
		{
			return null;
		}
		renderPath(graphics, path);
		return null;
	}

	private void renderPath(Graphics2D graphics, List<WorldPoint> path)
	{
		Player player = client.getLocalPlayer();
		WorldView worldView = client.getTopLevelWorldView();
		if (worldView == null)
		{
			return;
		}
		Point centre = player == null ? null : toMinimap(player.getWorldLocation(), worldView, player);
		Path2D.Float line = PathLine.build(path, player == null ? null : player.getWorldLocation(), centre,
			tile -> toMinimap(tile, worldView, player));
		if (line == null)
		{
			return;
		}
		Shape oldClip = graphics.getClip();
		if (centre != null)
		{
			// The path is projected well past the minimap's edge, so keep the line inside the circle.
			graphics.clip(new Ellipse2D.Float(centre.getX() - MINIMAP_CLIP_RADIUS, centre.getY() - MINIMAP_CLIP_RADIUS,
				MINIMAP_CLIP_RADIUS * 2, MINIMAP_CLIP_RADIUS * 2));
		}
		PathLine.draw(graphics, line, PATH_OUTLINE, PATH_LINE, config.highlightColour());
		graphics.setClip(oldClip);
	}

	private Point toMinimap(WorldPoint tile, WorldView worldView, Player player)
	{
		if (tile == null)
		{
			return null;
		}
		LocalPoint local = LocalPoint.fromWorld(worldView, tile);
		if (local == null && player != null && player.getWorldLocation() != null)
		{
			LocalPoint here = player.getLocalLocation();
			WorldPoint playerWorld = player.getWorldLocation();
			if (here != null && playerWorld.getPlane() == tile.getPlane())
			{
				int x = here.getX() + (tile.getX() - playerWorld.getX()) * Perspective.LOCAL_TILE_SIZE;
				int y = here.getY() + (tile.getY() - playerWorld.getY()) * Perspective.LOCAL_TILE_SIZE;
				local = new LocalPoint(x, y, worldView);
			}
		}
		if (local == null)
		{
			return null;
		}
		return Perspective.localToMinimap(client, local, MINIMAP_RANGE);
	}
}

