package com.mixologybeltrunner;

/**
 * One potion in an inventory slot: what it is, whether it has been through its
 * station yet, and which station it went (or is planned to go) through.
 */
public final class PotionSlot
{
	private final PotionType type;
	private final boolean processed;
	private final Station station;
	private final boolean digweed;

	public PotionSlot(PotionType type, boolean processed, Station station, boolean digweed)
	{
		this.type = type;
		this.processed = processed;
		this.station = station;
		this.digweed = digweed;
	}

	public PotionType type()
	{
		return type;
	}

	public boolean processed()
	{
		return processed;
	}

	public Station station()
	{
		return station;
	}

	public boolean digweed()
	{
		return digweed;
	}

	public PotionSlot processedAt(Station s)
	{
		return new PotionSlot(type, true, s, digweed);
	}

	public PotionSlot withDigweed()
	{
		return new PotionSlot(type, processed, station, true);
	}

	public int expectedItemId()
	{
		return processed ? type.finishedId() : type.unfinishedId();
	}
}

package com.mixologybeltrunner;

import static com.mixologybeltrunner.PotionComponent.AGA;
import static com.mixologybeltrunner.PotionComponent.LYE;
import static com.mixologybeltrunner.PotionComponent.MOX;
import net.runelite.api.gameval.ItemID;

/**
 * Declared in game index order: index is the order/station varbit value minus one.
 */
public enum PotionType
{
	MAMMOTH_MIGHT_MIX("Mammoth-might mix", ItemID.MM_POTION_MMM_UNFINISHED, ItemID.MM_POTION_MMM_FINISHED, 1900, MOX, MOX, MOX),
	MYSTIC_MANA_AMALGAM("Mystic mana amalgam", ItemID.MM_POTION_MMA_UNFINISHED, ItemID.MM_POTION_MMA_FINISHED, 2150, MOX, MOX, AGA),
	MARLEYS_MOONLIGHT("Marley's moonlight", ItemID.MM_POTION_MML_UNFINISHED, ItemID.MM_POTION_MML_FINISHED, 2400, MOX, MOX, LYE),
	ALCO_AUGMENTATOR("Alco-augmentator", ItemID.MM_POTION_AAA_UNFINISHED, ItemID.MM_POTION_AAA_FINISHED, 1900, AGA, AGA, AGA),
	AZURE_AURA_MIX("Azure aura mix", ItemID.MM_POTION_AAM_UNFINISHED, ItemID.MM_POTION_AAM_FINISHED, 2650, AGA, AGA, MOX),
	AQUALUX_AMALGAM("Aqualux amalgam", ItemID.MM_POTION_AAL_UNFINISHED, ItemID.MM_POTION_AAL_FINISHED, 2900, AGA, LYE, AGA),
	LIPLACK_LIQUOR("Liplack liquor", ItemID.MM_POTION_LLL_UNFINISHED, ItemID.MM_POTION_LLL_FINISHED, 1900, LYE, LYE, LYE),
	MEGALITE_LIQUID("Megalite liquid", ItemID.MM_POTION_LLM_UNFINISHED, ItemID.MM_POTION_LLM_FINISHED, 3150, MOX, LYE, LYE),
	ANTI_LEECH_LOTION("Anti-leech lotion", ItemID.MM_POTION_LLA_UNFINISHED, ItemID.MM_POTION_LLA_FINISHED, 3400, AGA, LYE, LYE),
	MIXALOT("Mixalot", ItemID.MM_POTION_MAL_UNFINISHED, ItemID.MM_POTION_MAL_FINISHED, 3650, MOX, AGA, LYE);

	private static final PotionType[] TYPES = values();

	private final String itemName;
	private final int unfinishedId;
	private final int finishedId;
	private final int xp;
	private final PotionComponent[] components;
	private final String code;

	PotionType(String itemName, int unfinishedId, int finishedId, int xp, PotionComponent... components)
	{
		this.itemName = itemName;
		this.unfinishedId = unfinishedId;
		this.finishedId = finishedId;
		this.xp = xp;
		this.components = components;
		this.code = "" + components[0].letter() + components[1].letter() + components[2].letter();
	}

	/**
	 * The name the game uses in chat, such as "Mystic mana amalgam".
	 */
	public String itemName()
	{
		return itemName;
	}

	public int unfinishedId()
	{
		return unfinishedId;
	}

	public int finishedId()
	{
		return finishedId;
	}

	/**
	 * The Herblore level the potion needs.
	 */
	public int level()
	{
		switch (this)
		{
			case MYSTIC_MANA_AMALGAM:
				return 63;
			case MARLEYS_MOONLIGHT:
				return 66;
			case AZURE_AURA_MIX:
				return 69;
			case AQUALUX_AMALGAM:
				return 72;
			case MEGALITE_LIQUID:
				return 75;
			case ANTI_LEECH_LOTION:
				return 78;
			case MIXALOT:
				return 81;
			default:
				return 60;
		}
	}

	public int xp()
	{
		return xp;
	}

	public PotionComponent[] components()
	{
		return components.clone();
	}

	public String code()
	{
		return code;
	}

	public boolean isTriple()
	{
		return components[0] == components[1] && components[1] == components[2];
	}

	public int index()
	{
		return ordinal();
	}

	public boolean isFinishedItem(int id)
	{
		return id == finishedId;
	}

	public static PotionType fromIndex(int index)
	{
		return index >= 0 && index < TYPES.length ? TYPES[index] : null;
	}

	public static PotionType fromItemId(int id)
	{
		for (PotionType type : TYPES)
		{
			if (type.unfinishedId == id || type.finishedId == id)
			{
				return type;
			}
		}
		return null;
	}

	/**
	 * The type with that in-game name, ignoring case, or null.
	 */
	public static PotionType fromItemName(String name)
	{
		for (PotionType type : TYPES)
		{
			if (type.itemName.equalsIgnoreCase(name))
			{
				return type;
			}
		}
		return null;
	}
}

package com.mixologybeltrunner;

/**
 * The short stretch after the game shows a bonus-click effect at the alembic or agitator,
 * during which one extra click on that station earns bonus experience.
 * <p>
 * The window is timed by the station's progress varbit, not by ticks: the alembic's ends
 * on the first progress update after the effect, the agitator's on the second.
 */
public class QuickActionWindow
{
	/**
	 * Ticks after the effect at which the window closes anyway, should a progress update
	 * never arrive.
	 */
	static final int SAFETY_TICKS = 3;

	private Station station;
	private int startTick;
	private int progressSeen;

	/**
	 * Opens a window when the effect shows on a station that holds a potion. The retort has none.
	 */
	public void onSpotAnim(Station s, boolean stationHoldsPotion, int tick)
	{
		if (!stationHoldsPotion || progressUpdates(s) == 0)
		{
			return;
		}
		station = s;
		startTick = tick;
		progressSeen = 0;
	}

	public void onSkillshotHit(Station s)
	{
		end(s);
	}

	public void onProgressDropped(Station s)
	{
		end(s);
	}

	/**
	 * Any update to a station's progress varbit.
	 */
	public void onProgress(Station s)
	{
		if (station == s && ++progressSeen >= progressUpdates(s))
		{
			station = null;
		}
	}

	public void onTick(int tick)
	{
		if (station != null && tick - startTick >= SAFETY_TICKS)
		{
			station = null;
		}
	}

	/**
	 * The station whose window is open, or null.
	 */
	public Station active()
	{
		return station;
	}

	public void reset()
	{
		station = null;
	}

	private void end(Station s)
	{
		if (station == s)
		{
			station = null;
		}
	}

	/**
	 * Progress updates the window lasts for; 0 for a station without one.
	 */
	private static int progressUpdates(Station s)
	{
		if (s == Station.ALEMBIC)
		{
			return 1;
		}
		if (s == Station.AGITATOR)
		{
			return 2;
		}
		return 0;
	}
}

package com.mixologybeltrunner;

import java.util.Arrays;
import java.util.Collection;
import java.util.List;
import java.util.function.Predicate;
import net.runelite.client.plugins.Plugin;

/**
 * Finds the other mixology plugins Belt Runner steps aside for.
 */
public final class RivalPlugins
{
	static final List<String> NAMES = Arrays.asList("Mastering Mixology", "Mastering Mixology Extended");

	private RivalPlugins()
	{
	}

	/**
	 * The name of the first active rival, or null.
	 */
	public static String activeRival(Collection<Plugin> plugins, Predicate<Plugin> isActive)
	{
		for (Plugin plugin : plugins)
		{
			String name = plugin.getName();
			if (NAMES.contains(name) && isActive.test(plugin))
			{
				return name;
			}
		}
		return null;
	}
}

package com.mixologybeltrunner;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.List;
import java.util.function.ToIntFunction;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;

/**
 * One line of the guide window made of coloured pieces of text: some pinned left, some pinned right.
 * A line made with {@link #wrapped} is a single piece of text that breaks between words to fit.
 */
final class SegmentLine implements LayoutableRenderableEntity
{
	private static final int LINE_PADDING = 2;

	private final Font font;
	private final List<String> leftText = new ArrayList<>();
	private final List<Color> leftColour = new ArrayList<>();
	private final List<String> rightText = new ArrayList<>();
	private final List<Color> rightColour = new ArrayList<>();
	private final List<String> cellText = new ArrayList<>();
	private final List<Color> cellColour = new ArrayList<>();
	private final List<Integer> cellCentre = new ArrayList<>();
	private boolean wrap;
	private final Rectangle bounds = new Rectangle();
	private Point location = new Point();
	private Dimension size = new Dimension(0, 0);

	SegmentLine(Font font)
	{
		this.font = font;
	}

	/**
	 * Text in one colour, broken onto as many lines as the window width needs.
	 */
	static SegmentLine wrapped(Font font, String text, Color colour)
	{
		SegmentLine line = new SegmentLine(font).left(text, colour);
		line.wrap = true;
		return line;
	}

	/**
	 * Breaks text between words so each line fits {@code maxWidth}. A word wider than
	 * that gets a line to itself rather than being cut.
	 */
	static List<String> wrap(String text, int maxWidth, ToIntFunction<String> widthOf)
	{
		List<String> lines = new ArrayList<>();
		StringBuilder line = new StringBuilder();
		for (String word : text.split(" "))
		{
			if (word.isEmpty())
			{
				continue;
			}
			if (line.length() > 0 && widthOf.applyAsInt(line + " " + word) > maxWidth)
			{
				lines.add(line.toString());
				line.setLength(0);
			}
			if (line.length() > 0)
			{
				line.append(' ');
			}
			line.append(word);
		}
		if (line.length() > 0 || lines.isEmpty())
		{
			lines.add(line.toString());
		}
		return lines;
	}

	SegmentLine left(String text, Color colour)
	{
		leftText.add(text);
		leftColour.add(colour);
		return this;
	}

	/**
	 * Adds a potion code, one letter per component in that component's colour.
	 */
	SegmentLine leftCode(PotionType type)
	{
		for (PotionComponent component : type.components())
		{
			left(String.valueOf(component.letter()), component.color());
		}
		return this;
	}

	SegmentLine right(String text, Color colour)
	{
		rightText.add(text);
		rightColour.add(colour);
		return this;
	}

	/**
	 * Adds text centred a fixed distance in from the right edge, so rows line up as columns.
	 */
	SegmentLine cell(String text, Color colour, int centreFromRight)
	{
		cellText.add(text);
		cellColour.add(colour);
		cellCentre.add(centreFromRight);
		return this;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		graphics.setFont(font);
		FontMetrics metrics = graphics.getFontMetrics();
		int height = metrics.getHeight() + LINE_PADDING;
		int width = size.width;
		int baseline = location.y + metrics.getAscent() + LINE_PADDING / 2;
		if (wrap)
		{
			List<String> lines = wrap(leftText.get(0), width, metrics::stringWidth);
			for (int i = 0; i < lines.size(); i++)
			{
				draw(graphics, lines.get(i), leftColour.get(0), location.x, baseline + i * metrics.getHeight());
			}
			return finish(width, height + (lines.size() - 1) * metrics.getHeight());
		}
		int x = location.x;
		for (int i = 0; i < leftText.size(); i++)
		{
			x += draw(graphics, leftText.get(i), leftColour.get(i), x, baseline);
		}
		int rightWidth = 0;
		for (String text : rightText)
		{
			rightWidth += metrics.stringWidth(text);
		}
		x = location.x + width - rightWidth;
		for (int i = 0; i < rightText.size(); i++)
		{
			x += draw(graphics, rightText.get(i), rightColour.get(i), x, baseline);
		}
		for (int i = 0; i < cellText.size(); i++)
		{
			int cellX = location.x + width - cellCentre.get(i) - metrics.stringWidth(cellText.get(i)) / 2;
			draw(graphics, cellText.get(i), cellColour.get(i), cellX, baseline);
		}
		return finish(width, height);
	}

	private Dimension finish(int width, int height)
	{
		Dimension used = new Dimension(width, height);
		bounds.setLocation(location);
		bounds.setSize(used);
		return used;
	}

	private static int draw(Graphics2D graphics, String text, Color colour, int x, int y)
	{
		graphics.setColor(Color.BLACK);
		graphics.drawString(text, x + 1, y + 1);
		graphics.setColor(colour);
		graphics.drawString(text, x, y);
		return graphics.getFontMetrics().stringWidth(text);
	}

	@Override
	public Rectangle getBounds()
	{
		return bounds;
	}

	@Override
	public void setPreferredLocation(Point position)
	{
		location = position;
	}

	@Override
	public void setPreferredSize(Dimension dimension)
	{
		size = dimension;
	}
}

package com.mixologybeltrunner;

import java.util.ArrayList;
import java.util.List;

/**
 * Which potion sits in each inventory slot and which station it went through.
 * The game does not expose that, so the plugin tracks it here.
 */
public final class SlotMap
{
	public static final int SIZE = 28;

	private final PotionSlot[] slots = new PotionSlot[SIZE];

	public PotionSlot get(int slot)
	{
		return slots[slot];
	}

	public void put(int slot, PotionSlot p)
	{
		slots[slot] = p;
	}

	public PotionSlot remove(int slot)
	{
		PotionSlot old = slots[slot];
		slots[slot] = null;
		return old;
	}

	/**
	 * Swaps two slots; either side may be empty.
	 */
	public void move(int from, int to)
	{
		PotionSlot tmp = slots[from];
		slots[from] = slots[to];
		slots[to] = tmp;
	}

	public int firstUnprocessed()
	{
		for (int i = 0; i < SIZE; i++)
		{
			if (slots[i] != null && !slots[i].processed())
			{
				return i;
			}
		}
		return -1;
	}

	public List<Integer> occupiedSlots()
	{
		List<Integer> out = new ArrayList<>();
		for (int i = 0; i < SIZE; i++)
		{
			if (slots[i] != null)
			{
				out.add(i);
			}
		}
		return out;
	}

	public int[] expectedItemIds()
	{
		int[] ids = new int[SIZE];
		for (int i = 0; i < SIZE; i++)
		{
			ids[i] = slots[i] == null ? -1 : slots[i].expectedItemId();
		}
		return ids;
	}

	public boolean isEmpty()
	{
		for (PotionSlot p : slots)
		{
			if (p != null)
			{
				return false;
			}
		}
		return true;
	}

	public int countCovered(Cell c)
	{
		return count(c, false);
	}

	public int countFinished(Cell c)
	{
		return count(c, true);
	}

	private int count(Cell c, boolean finishedOnly)
	{
		int n = 0;
		for (PotionSlot p : slots)
		{
			if (p != null && p.type() == c.type() && p.station() == c.station()
				&& (!finishedOnly || p.processed()))
			{
				n++;
			}
		}
		return n;
	}

	public SlotMap copy()
	{
		SlotMap m = new SlotMap();
		System.arraycopy(slots, 0, m.slots, 0, SIZE);
		return m;
	}

	/**
	 * A copy with every unprocessed entry marked processed at its planned station.
	 */
	public SlotMap assumingProcessed()
	{
		SlotMap m = copy();
		for (int i = 0; i < SIZE; i++)
		{
			PotionSlot p = m.slots[i];
			if (p != null && !p.processed())
			{
				m.slots[i] = p.processedAt(p.station());
			}
		}
		return m;
	}
}

package com.mixologybeltrunner;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.util.ArrayList;
import java.util.List;

/**
 * Reads and writes the slot map as JSON so it survives a relog.
 */
public final class SlotMapCodec
{
	private SlotMapCodec()
	{
	}

	private static final class Entry
	{
		private int slot;
		private String type;
		private boolean processed;
		private String station;
		private boolean digweed;
	}

	public static String encode(Gson gson, SlotMap map)
	{
		List<Entry> out = new ArrayList<>();
		for (int slot : map.occupiedSlots())
		{
			PotionSlot p = map.get(slot);
			Entry e = new Entry();
			e.slot = slot;
			e.type = p.type().code();
			e.processed = p.processed();
			e.station = p.station().name();
			e.digweed = p.digweed();
			out.add(e);
		}
		return gson.toJson(out);
	}

	/**
	 * Returns null when the text is missing, malformed or names anything unknown.
	 */
	public static SlotMap decode(Gson gson, String json)
	{
		if (json == null || json.trim().isEmpty())
		{
			return null;
		}
		Entry[] entries;
		try
		{
			entries = gson.fromJson(json, Entry[].class);
		}
		catch (JsonParseException e)
		{
			return null;
		}
		if (entries == null)
		{
			return null;
		}
		SlotMap map = new SlotMap();
		for (Entry e : entries)
		{
			if (e == null || e.slot < 0 || e.slot >= SlotMap.SIZE)
			{
				return null;
			}
			PotionType type = typeOf(e.type);
			Station station = stationOf(e.station);
			if (type == null || station == null)
			{
				return null;
			}
			map.put(e.slot, new PotionSlot(type, e.processed, station, e.digweed));
		}
		return map;
	}

	private static PotionType typeOf(String code)
	{
		for (PotionType t : PotionType.values())
		{
			if (t.code().equals(code))
			{
				return t;
			}
		}
		return null;
	}

	private static Station stationOf(String name)
	{
		for (Station s : Station.values())
		{
			if (s.name().equals(name))
			{
				return s;
			}
		}
		return null;
	}
}

package com.mixologybeltrunner;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.client.util.Text;

public enum Station
{
	ALEMBIC("Crystalise-potion", "Alembic", "Alem", LabObject.ALEMBIC),
	RETORT("Concentrate-potion", "Retort", "Reto", LabObject.RETORT),
	AGITATOR("Homogenise-potion", "Agitator", "Agit", LabObject.AGITATOR);

	public static final List<Station> PROCESS_ORDER =
		Collections.unmodifiableList(Arrays.asList(ALEMBIC, RETORT, AGITATOR));

	private final String menuOption;
	private final String displayName;
	private final String shortName;
	private final LabObject object;

	Station(String menuOption, String displayName, String shortName, LabObject object)
	{
		this.menuOption = menuOption;
		this.displayName = displayName;
		this.shortName = shortName;
		this.object = object;
	}

	/**
	 * The right-click option the game shows on the station object.
	 */
	public String menuOption()
	{
		return menuOption;
	}

	public String displayName()
	{
		return displayName;
	}

	public String shortName()
	{
		return shortName;
	}

	public LabObject object()
	{
		return object;
	}

	/**
	 * Maps the order modifier varbit value to the station it asks for, or null.
	 */
	public static Station fromOrderModifier(int varbitValue)
	{
		switch (varbitValue)
		{
			case 1:
				return AGITATOR;
			case 2:
				return RETORT;
			case 3:
				return ALEMBIC;
			default:
				return null;
		}
	}

	/**
	 * Resolves a raw menu target, colour tags included, to a station, or null.
	 */
	public static Station fromMenuTarget(String rawTarget)
	{
		if (rawTarget == null)
		{
			return null;
		}
		String target = Text.removeTags(rawTarget);
		for (Station station : values())
		{
			if (station.displayName.equalsIgnoreCase(target))
			{
				return station;
			}
		}
		return null;
	}
}

