package com.mixologybeltrunner;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.List;
import java.util.function.ToIntFunction;
import net.runelite.client.ui.FontManager;
import org.junit.Test;

public class SegmentLineTest
{
	/**
	 * Six pixels a character.
	 */
	private static final ToIntFunction<String> MONO = s -> s.length() * 6;
	/**
	 * The guide window is 200 wide with a 4 pixel border each side.
	 */
	private static final int LINE_WIDTH = 192;

	@Test
	public void shortTextStaysOnOneLine()
	{
		assertEquals(List.of("Click the belt"), SegmentLine.wrap("Click the belt", LINE_WIDTH, MONO));
	}

	@Test
	public void longTextBreaksBetweenWords()
	{
		assertEquals(List.of("Deposit or destroy your potions", "to start"),
			SegmentLine.wrap("Deposit or destroy your potions to start", LINE_WIDTH, MONO));
	}

	@Test
	public void overlongWordGetsItsOwnLine()
	{
		assertEquals(List.of("a", "abcdefgh", "b"), SegmentLine.wrap("a abcdefgh b", 30, MONO));
	}

	@Test
	public void emptyTextIsOneEmptyLine()
	{
		assertEquals(List.of(""), SegmentLine.wrap("", LINE_WIDTH, MONO));
	}

	@Test
	public void windowTextFitsInTheRunescapeFonts()
	{
		Graphics2D g = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB).createGraphics();
		FontMetrics bold = g.getFontMetrics(FontManager.getRunescapeBoldFont());
		FontMetrics small = g.getFontMetrics(FontManager.getRunescapeSmallFont());
		assertFits(bold, "Deposit or destroy your potions to start", 2);
		assertFits(bold, "Click the belt (skipping LLL, AAA)", 2);
		assertFits(bold, "Belt Runner needs Herblore 81", 2);
		assertFits(bold, "Make MML → Retort", 1);
		assertFits(small, "Potions were already in the inventory when tracking started.", 2);
		assertFits(small, "Restocking · round 1 of 3 · stock 0 / 21 · digweed ready", 2);
		g.dispose();
	}

	private static void assertFits(FontMetrics metrics, String text, int expectedLines)
	{
		List<String> lines = SegmentLine.wrap(text, LINE_WIDTH, metrics::stringWidth);
		assertEquals(text, expectedLines, lines.size());
		for (String line : lines)
		{
			assertTrue(line + " is " + metrics.stringWidth(line) + " px", metrics.stringWidth(line) <= LINE_WIDTH);
		}
	}
}

package com.mixologybeltrunner;

import static com.mixologybeltrunner.PotionType.AQUALUX_AMALGAM;
import static com.mixologybeltrunner.PotionType.MIXALOT;
import static com.mixologybeltrunner.Station.AGITATOR;
import static com.mixologybeltrunner.Station.RETORT;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import org.junit.Test;

public class SlotMapCodecTest
{
	private final Gson gson = new Gson();

	@Test
	public void roundTrip()
	{
		SlotMap m = new SlotMap();
		m.put(3, new PotionSlot(MIXALOT, true, RETORT, true));
		m.put(9, new PotionSlot(AQUALUX_AMALGAM, false, AGITATOR, false));
		SlotMap back = SlotMapCodec.decode(gson, SlotMapCodec.encode(gson, m));
		assertArrayEquals(m.expectedItemIds(), back.expectedItemIds());
		assertTrue(back.get(3).digweed());
		assertEquals(AGITATOR, back.get(9).station());
	}

	@Test
	public void garbageDecodesToNull()
	{
		assertNull(SlotMapCodec.decode(gson, "not json"));
		assertNull(SlotMapCodec.decode(gson, "[{\"slot\":40,\"type\":\"MAL\",\"processed\":true,\"station\":\"RETORT\",\"digweed\":false}]"));
		assertNull(SlotMapCodec.decode(gson, "[{\"slot\":1,\"type\":\"XYZ\",\"processed\":true,\"station\":\"RETORT\",\"digweed\":false}]"));
		assertNull(SlotMapCodec.decode(gson, "[{\"slot\":1,\"type\":\"MAL\",\"processed\":true,\"station\":\"NOPE\",\"digweed\":false}]"));
		assertNull(SlotMapCodec.decode(gson, null));
		assertNull(SlotMapCodec.decode(gson, "  "));
	}

	@Test
	public void emptyMapRoundTrips()
	{
		SlotMap back = SlotMapCodec.decode(gson, SlotMapCodec.encode(gson, new SlotMap()));
		assertTrue(back.isEmpty());
	}
}

package com.mixologybeltrunner;

import static com.mixologybeltrunner.Fixtures.fin;
import static com.mixologybeltrunner.Fixtures.unf;
import static com.mixologybeltrunner.PotionType.MIXALOT;
import static com.mixologybeltrunner.PotionType.MYSTIC_MANA_AMALGAM;
import static com.mixologybeltrunner.Station.AGITATOR;
import static com.mixologybeltrunner.Station.ALEMBIC;
import static com.mixologybeltrunner.Station.RETORT;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import org.junit.Test;

public class SlotMapTest
{
	@Test
	public void swapOfIdenticalPotionsSwapsStations()
	{
		SlotMap m = new SlotMap();
		m.put(0, fin(MYSTIC_MANA_AMALGAM, ALEMBIC));
		m.put(1, fin(MYSTIC_MANA_AMALGAM, RETORT));
		m.move(0, 1);
		assertEquals(RETORT, m.get(0).station());
		assertEquals(ALEMBIC, m.get(1).station());
	}

	@Test
	public void moveIntoEmptySlot()
	{
		SlotMap m = new SlotMap();
		m.put(2, fin(MYSTIC_MANA_AMALGAM, AGITATOR));
		m.move(2, 3);
		assertNull(m.get(2));
		assertEquals(AGITATOR, m.get(3).station());
	}

	@Test
	public void firstUnprocessedSkipsFinished()
	{
		SlotMap m = new SlotMap();
		m.put(0, fin(MIXALOT, ALEMBIC));
		m.put(4, unf(MIXALOT, RETORT));
		m.put(6, unf(MIXALOT, AGITATOR));
		assertEquals(4, m.firstUnprocessed());
	}

	@Test
	public void expectedIdsAndAssumingProcessed()
	{
		SlotMap m = new SlotMap();
		m.put(1, unf(MIXALOT, RETORT));
		assertEquals(MIXALOT.unfinishedId(), m.expectedItemIds()[1]);
		assertEquals(-1, m.expectedItemIds()[0]);
		SlotMap a = m.assumingProcessed();
		assertTrue(a.get(1).processed());
		assertFalse(m.get(1).processed());
		assertEquals(1, a.countFinished(new Cell(MIXALOT, RETORT)));
	}

	@Test
	public void occupiedEmptyRemoveAndCounts()
	{
		SlotMap m = new SlotMap();
		assertTrue(m.isEmpty());
		assertEquals(-1, m.firstUnprocessed());
		m.put(5, fin(MIXALOT, RETORT));
		m.put(2, unf(MIXALOT, RETORT));
		assertEquals(Arrays.asList(2, 5), m.occupiedSlots());
		Cell c = new Cell(MIXALOT, RETORT);
		assertEquals(2, m.countCovered(c));
		assertEquals(1, m.countFinished(c));
		assertEquals(MIXALOT.finishedId(), m.expectedItemIds()[5]);
		assertEquals(2, m.remove(2).type() == MIXALOT ? 2 : 0);
		assertNull(m.get(2));
		assertFalse(m.isEmpty());
	}
}

